insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('85005b27-1670-5fc5-bc13-a1060453bfc4', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '68', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَتَانَا مُنَادِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ وَرَسُولَهُ يَنْهَاكُمْ عَنْ لُحُومِ الْحُمُرِ فَإِنَّهَا ‏ ‏رِجْسٌ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('474ae36f-a02a-5cbb-8ace-bdc95430d845', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '69', '‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَتَعَرَّقُ ‏ ‏الْعَرْقَ ‏ ‏فَيَضَعُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاهُ حَيْثُ وَضَعْتُ وَأَنَا حَائِضٌ وَكُنْتُ أَشْرَبُ مِنْ الْإِنَاءِ فَيَضَعُ فَاهُ حَيْثُ وَضَعْتُ وَأَنَا حَائِضٌ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7e236b22-519d-5942-8f16-e01dd66151a9', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '70', '‏ ‏أَخْبَرَنِي ‏ ‏هَارُونُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏ح ‏ ‏وَالْحَارِثُ بْنُ مِسْكِينٍ ‏ ‏قِرَاءَةً عَلَيْهِ وَأَنَا أَسْمَعُ عَنْ ‏ ‏ابْنِ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ الرِّجَالُ وَالنِّسَاءُ يَتَوَضَّئُونَ فِي زَمَانِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمِيعًا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('344df425-ef9c-5073-af1c-9552dea80206', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '71', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا أَخْبَرَتْهُ ‏ ‏أَنَّهَا ‏ ‏كَانَتْ تَغْتَسِلُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْإِنَاءِ الْوَاحِدِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fa8574e1-553c-508b-ab32-5ae44c70e5c1', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '72', '‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏بِمَكُّوكٍ ‏ ‏وَيَغْتَسِلُ بِخَمْسِ ‏ ‏مَكَاكِيَّ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('43809dff-f27e-56fc-89d8-ee592df17bb4', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '73', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ ‏ ‏ثُمَّ ذَكَرَ كَلِمَةً مَعْنَاهَا ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبَّادَ بْنَ تَمِيمٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَدَّتِي وَهِيَ ‏ ‏أُمُّ عُمَارَةَ بِنْتُ كَعْبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَأُتِيَ بِمَاءٍ فِي إِنَاءٍ قَدْرَ ثُلُثَيْ ‏ ‏الْمُدِّ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَأَحْفَظُ أَنَّهُ غَسَلَ ذِرَاعَيْهِ وَجَعَلَ يَدْلُكُهُمَا وَيَمْسَحُ أُذُنَيْهِ بَاطِنَهُمَا وَلَا أَحْفَظُ أَنَّهُ مَسَحَ ظَاهِرَهُمَا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('98755535-9e41-57c8-9a8e-27a90e1bede5', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '74', '‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَبِيبِ بْنِ عَرَبِيٍّ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏وَالْحَارِثُ بْنُ مِسْكِينٍ ‏ ‏قِرَاءَةً عَلَيْهِ وَأَنَا أَسْمَعُ عَنْ ‏ ‏ابْنِ الْقَاسِمِ ‏ ‏حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏ح ‏ ‏و أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ مَنْصُورٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ وَقَّاصٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا الْأَعْمَالُ ‏ ‏بِالنِّيَّةِ ‏ ‏وَإِنَّمَا لِامْرِئٍ مَا نَوَى فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَإِلَى رَسُولِهِ فَهِجْرَتُهُ إِلَى اللَّهِ وَإِلَى رَسُولِهِ وَمَنْ كَانَتْ هِجْرَتُهُ إِلَى دُنْيَا يُصِيبُهَا أَوْ امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0299b3c7-d4f4-56d5-bbf0-05e5b416770f', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '75', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحَانَتْ صَلَاةُ الْعَصْرِ فَالْتَمَسَ النَّاسُ الْوَضُوءَ فَلَمْ يَجِدُوهُ فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِوَضُوءٍ ‏ ‏فَوَضَعَ يَدَهُ فِي ذَلِكَ الْإِنَاءِ وَأَمَرَ النَّاسَ أَنْ يَتَوَضَّئُوا فَرَأَيْتُ الْمَاءَ يَنْبُعُ مِنْ تَحْتِ أَصَابِعِهِ حَتَّى تَوَضَّئُوا مِنْ عِنْدِ آخِرِهِمْ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('aca74846-df78-5602-b910-7ad29e9c574d', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '76', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَجِدُوا مَاءً ‏ ‏فَأُتِيَ ‏ ‏بِتَوْرٍ ‏ ‏فَأَدْخَلَ يَدَهُ فَلَقَدْ رَأَيْتُ الْمَاءَ يَتَفَجَّرُ مِنْ بَيْنِ أَصَابِعِهِ وَيَقُولُ حَيَّ عَلَى الطَّهُورِ وَالْبَرَكَةِ مِنْ اللَّهِ عَزَّ وَجَلَّ ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏فَحَدَّثَنِي ‏ ‏سَالِمُ بْنُ أَبِي الْجَعْدِ ‏ ‏قَالَ قُلْتُ ‏ ‏لِجَابِرٍ ‏ ‏كَمْ كُنْتُمْ يَوْمَئِذٍ قَالَ أَلْفٌ وَخَمْسُ مِائَةٍ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('86c37829-70b9-556c-b70d-608d9e8186c8', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '77', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏وَقَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏طَلَبَ بَعْضُ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَضُوءًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ مَعَ أَحَدٍ مِنْكُمْ مَاءٌ ‏ ‏فَوَضَعَ يَدَهُ فِي الْمَاءِ وَيَقُولُ تَوَضَّئُوا بِسْمِ اللَّهِ فَرَأَيْتُ الْمَاءَ يَخْرُجُ مِنْ بَيْنِ أَصَابِعِهِ حَتَّى تَوَضَّئُوا مِنْ عِنْدِ آخِرِهِمْ ‏ ‏قَالَ ‏ ‏ثَابِتٌ ‏ ‏قُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏كَمْ ‏ ‏تُرَاهُمْ قَالَ نَحْوًا مِنْ سَبْعِينَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('18386869-59c9-5d86-9613-1daba4dbf0f7', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '78', '‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏وَالْحَارِثُ بْنُ مِسْكِينٍ ‏ ‏قِرَاءَةً عَلَيْهِ وَأَنَا أَسْمَعُ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏عَنْ ‏ ‏ابْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏وَيُونُسَ ‏ ‏وَعَمْرِو بْنِ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏ابْنَ شِهَابٍ ‏ ‏أَخْبَرَهُمْ عَنْ ‏ ‏عَبَّادِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يَقُولُ ‏ ‏سَكَبْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ تَوَضَّأَ فِي ‏ ‏غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏فَمَسَحَ عَلَى الْخُفَّيْنِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏لَمْ يَذْكُرْ ‏ ‏مَالِكٌ ‏ ‏عُرْوَةَ بْنَ الْمُغِيرَةِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1b90079a-0a39-5d7e-9b08-fba0cdb1ad7d', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '79', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِوُضُوءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَوَضَّأَ مَرَّةً مَرَّةً ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('485f669c-3376-5a57-b673-2401aa661d58', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '80', '‏ ‏أَخْبَرَنَا ‏ ‏سُوَيْدُ بْنُ نَصْرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْمُطَّلِبُ بْنُ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏تَوَضَّأَ ثَلَاثًا ثَلَاثًا يُسْنَدُ ذَلِكَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f7233c62-36d9-5b81-b70f-f43b33cd5a36', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '81', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ الْبَصْرِيُّ ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ الْمُفَضَّلِ ‏ ‏عَنْ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ ‏ ‏وَعَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏حَتَّى رَدَّهُ إِلَى ‏ ‏الْمُغِيرَةِ ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏وَلَا أَحْفَظُ حَدِيثَ ذَا مِنْ حَدِيثِ ذَا ‏ ‏أَنَّ ‏ ‏الْمُغِيرَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ‏ ‏فَقَرَعَ ‏ ‏ظَهْرِي بِعَصًا كَانَتْ مَعَهُ ‏ ‏فَعَدَلَ ‏ ‏وَعَدَلْتُ ‏ ‏مَعَهُ حَتَّى أَتَى كَذَا وَكَذَا مِنْ الْأَرْضِ ‏ ‏فَأَنَاخَ ‏ ‏ثُمَّ انْطَلَقَ قَالَ فَذَهَبَ حَتَّى ‏ ‏تَوَارَى ‏ ‏عَنِّي ثُمَّ جَاءَ فَقَالَ أَمَعَكَ مَاءٌ وَمَعِي ‏ ‏سَطِيحَةٌ ‏ ‏لِي فَأَتَيْتُهُ بِهَا فَأَفْرَغْتُ عَلَيْهِ ‏ ‏فَغَسَلَ يَدَيْهِ وَوَجْهَهُ وَذَهَبَ لِيَغْسِلَ ذِرَاعَيْهِ وَعَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏شَامِيَّةٌ ضَيِّقَةُ الْكُمَّيْنِ فَأَخْرَجَ يَدَهُ مِنْ تَحْتِ ‏ ‏الْجُبَّةِ ‏ ‏فَغَسَلَ وَجْهَهُ وَذِرَاعَيْهِ وَذَكَرَ مِنْ ‏ ‏نَاصِيَتِهِ ‏ ‏شَيْئًا وَعِمَامَتِهِ شَيْئًا ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏لَا أَحْفَظُ كَمَا أُرِيدُ ‏ ‏ثُمَّ مَسَحَ عَلَى خُفَّيْهِ ثُمَّ قَالَ حَاجَتَكَ قُلْتُ يَا رَسُولَ اللَّهِ لَيْسَتْ لِي حَاجَةٌ فَجِئْنَا وَقَدْ أَمَّ النَّاسَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ ‏ ‏وَقَدْ صَلَّى بِهِمْ رَكْعَةً مِنْ صَلَاةِ الصُّبْحِ فَذَهَبْتُ ‏ ‏لِأُوذِنَهُ ‏ ‏فَنَهَانِي فَصَلَّيْنَا مَا أَدْرَكْنَا وَقَضَيْنَا مَا سُبِقْنَا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bfeff14d-bedf-5e43-ac94-c33aeb9a3b7a', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '82', '‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدُ بْنُ مَسْعَدَةَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ وَهُوَ ابْنُ حَبِيبٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَوْسِ بْنِ أَبِي أَوْسٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَوْكَفَ ‏ ‏ثَلَاثًا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4fad9e8e-53f4-5ca3-b416-13e01735aaff', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '83', '‏ ‏أَخْبَرَنَا ‏ ‏سُوَيْدُ بْنُ نَصْرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏حُمْرَانَ بْنِ أَبَانَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏تَوَضَّأَ فَأَفْرَغَ عَلَى يَدَيْهِ ثَلَاثًا فَغَسَلَهُمَا ثُمَّ تَمَضْمَضَ وَاسْتَنْشَقَ ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا ثُمَّ غَسَلَ يَدَيْهِ الْيُمْنَى إِلَى ‏ ‏الْمِرْفَقِ ‏ ‏ثَلَاثًا ثُمَّ الْيُسْرَى مِثْلَ ذَلِكَ ثُمَّ مَسَحَ بِرَأْسِهِ ثُمَّ غَسَلَ قَدَمَهُ الْيُمْنَى ثَلَاثًا ثُمَّ الْيُسْرَى مِثْلَ ذَلِكَ ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ نَحْوَ وُضُوئِي ثُمَّ قَالَ مَنْ تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا ثُمَّ صَلَّى رَكْعَتَيْنِ لَا يُحَدِّثُ نَفْسَهُ فِيهِمَا بِشَيْءٍ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('06443e81-43ed-5ed6-b900-148913a2ca9a', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '84', '‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ مُحَمَّدِ بْنِ الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُثْمَانُ هُوَ ابْنُ سَعِيدِ بْنِ كَثِيرِ بْنِ دِينَارٍ الْحِمْصِيُّ ‏ ‏عَنْ ‏ ‏شُعَيْبٍ هُوَ ابْنُ أبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏أَنَّهُ رَأَى ‏ ‏عُثْمَانَ ‏ ‏دَعَا بِوَضُوءٍ فَأَفْرَغَ عَلَى يَدَيْهِ مِنْ إِنَائِهِ فَغَسَلَهَا ثَلَاثَ مَرَّاتٍ ثُمَّ أَدْخَلَ يَمِينَهُ فِي الْوَضُوءِ فَتَمَضْمَضَ وَاسْتَنْشَقَ ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ إِلَى الْمِرْفَقَيْنِ ثَلَاثَ مَرَّاتٍ ثُمَّ مَسَحَ بِرَأْسِهِ ثُمَّ غَسَلَ كُلَّ رِجْلٍ مِنْ رِجْلَيْهِ ثَلَاثَ مَرَّاتٍ ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وُضُوئِي هَذَا ثُمَّ قَالَ مَنْ تَوَضَّأَ مِثْلَ وُضُوئِي هَذَا ثُمَّ قَامَ فَصَلَّى رَكْعَتَيْنِ لَا يُحَدِّثُ فِيهِمَا نَفْسَهُ بِشَيْءٍ غَفَرَ اللَّهُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('70f6a006-db8c-5615-9329-621d05ab7832', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '85', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الزِّنَادِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏الْحُسَيْنُ بْنُ عِيسَى ‏ ‏عَنْ ‏ ‏مَعْنٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأَ أَحَدُكُمْ فَلْيَجْعَلْ فِي أَنْفِهِ مَاءً ثُمَّ ‏ ‏لِيَسْتَنْثِرْ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2bc03e07-477f-5f62-b54d-cb8c9d26250b', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '86', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ كَثِيرٍ ‏ ‏ح ‏ ‏وَأَنْبَأَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ لَقِيطِ بْنِ صَبْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَخْبِرْنِي عَنْ الْوُضُوءِ قَالَ ‏ ‏أَسْبِغْ ‏ ‏الْوُضُوءَ وَبَالِغْ فِي ‏ ‏الِاسْتِنْشَاقِ إِلَّا أَنْ تَكُونَ صَائِمًا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1c03d1ee-6888-54f5-a8cd-66e03e6f626b', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '87', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْخَوْلَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَوَضَّأَ ‏ ‏فَلْيَسْتَنْثِرْ ‏ ‏وَمَنْ ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيُوتِرْ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e0adceb6-4ed2-50de-838b-07338a713a40', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '88', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ قَيْسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأْتَ ‏ ‏فَاسْتَنْثِرْ ‏ ‏وَإِذَا ‏ ‏اسْتَجْمَرْتَ ‏ ‏فَأَوْتِرْ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f1c7cb35-ff8a-55e0-84b9-85f739661fdd', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '89', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ زُنْبُورٍ الْمَكِّيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ إِبْرَاهِيمَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ مَنَامِهِ فَتَوَضَّأَ ‏ ‏فَلْيَسْتَنْثِرْ ‏ ‏ثَلَاثَ مَرَّاتٍ فَإِنَّ الشَّيْطَانَ يَبِيتُ عَلَى خَيْشُومِهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2bdb5d18-be37-50c5-89cb-606369f57b59', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '90', '‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدُ بْنُ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏أَنَّهُ ‏ ‏دَعَا بِوَضُوءٍ فَتَمَضْمَضَ وَاسْتَنْشَقَ ‏ ‏وَنَثَرَ ‏ ‏بِيَدِهِ الْيُسْرَى فَفَعَلَ هَذَا ثَلَاثًا ثُمَّ قَالَ هَذَا طُهُورُ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cb8c9fdf-102e-5326-a43a-3d0643588299', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '91', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏قَالَ ‏ ‏أَتَيْنَا ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَقَدْ صَلَّى فَدَعَا بِطَهُورٍ فَقُلْنَا مَا يَصْنَعُ بِهِ وَقَدْ صَلَّى مَا يُرِيدُ إِلَّا لِيُعَلِّمَنَا فَأُتِيَ بِإِنَاءٍ فِيهِ مَاءٌ وَطَسْتٍ ‏ ‏فَأَفْرَغَ مِنْ الْإِنَاءِ عَلَى يَدَيْهِ فَغَسَلَهَا ثَلَاثًا ثُمَّ تَمَضْمَضَ وَاسْتَنْشَقَ ثَلَاثًا مِنْ الْكَفِّ الَّذِي يَأْخُذُ بِهِ الْمَاءَ ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا وَغَسَلَ يَدَهُ الْيُمْنَى ثَلَاثًا وَيَدَهُ الشِّمَالَ ثَلَاثًا وَمَسَحَ بِرَأْسِهِ مَرَّةً وَاحِدَةً ثُمَّ غَسَلَ رِجْلَهُ الْيُمْنَى ثَلَاثًا وَرِجْلَهُ الشِّمَالَ ثَلَاثًا ثُمَّ قَالَ مَنْ سَرَّهُ أَنْ يَعْلَمَ وُضُوءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهُوَ هَذَا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('54f82d6c-bf77-5747-8a12-3f3aa8603ec4', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '92', '‏ ‏أَخْبَرَنَا ‏ ‏سُوَيْدُ بْنُ نَصْرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عَبْدُ اللَّهِ وَهُوَ ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ عُرْفُطَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ أُتِيَ بِكُرْسِيٍّ فَقَعَدَ عَلَيْهِ ثُمَّ ‏ ‏دَعَا ‏ ‏بِتَوْرٍ ‏ ‏فِيهِ مَاءٌ فَكَفَأَ عَلَى يَدَيْهِ ثَلَاثًا ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ بِكَفٍّ وَاحِدٍ ثَلَاثَ مَرَّاتٍ وَغَسَلَ وَجْهَهُ ثَلَاثًا وَغَسَلَ ذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا وَأَخَذَ مِنْ الْمَاءِ فَمَسَحَ بِرَأْسِهِ وَأَشَارَ ‏ ‏شُعْبَةُ ‏ ‏مَرَّةً مِنْ ‏ ‏نَاصِيَتِهِ ‏ ‏إِلَى مُؤَخَّرِ رَأْسِهِ ثُمَّ قَالَ ‏ ‏لَا أَدْرِي أَرَدَّهُمَا أَمْ لَا ‏ ‏وَغَسَلَ رِجْلَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ قَالَ مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى طُهُورِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهَذَا طُهُورُهُ ‏ ‏و قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏هَذَا خَطَأٌ وَالصَّوَابُ ‏ ‏خَالِدُ بْنُ عَلْقَمَةَ ‏ ‏لَيْسَ ‏ ‏مَالِكَ بْنَ عُرْفُطَةَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fdeac8b3-94d4-56ba-ab9f-f1320cf4d58b', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '93', '‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏وَحُمَيْدُ بْنُ مَسْعَدَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ وَهُوَ ابْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ عُرْفُطَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏عَلِيًّا ‏ ‏دَعَا بِكُرْسِيٍّ فَقَعَدَ عَلَيْهِ ثُمَّ ‏ ‏دَعَا بِمَاءٍ فِي ‏ ‏تَوْرٍ ‏ ‏فَغَسَلَ يَدَيْهِ ثَلَاثًا ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ بِكَفٍّ وَاحِدٍ ثَلَاثًا ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ غَمَسَ يَدَهُ فِي الْإِنَاءِ فَمَسَحَ بِرَأْسِهِ ثُمَّ غَسَلَ رِجْلَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ قَالَ مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى وُضُوءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهَذَا وُضُوءُهُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fee0a098-026c-5d79-a70d-efc011adef7d', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '94', '‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْحَسَنِ الْمِقْسَمِيُّ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏شَيْبَةُ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ عَلِيٍّ ‏ ‏أَخْبَرَهُ قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَلِيٌّ ‏ ‏أَنَّ ‏ ‏الْحُسَيْنَ بْنَ عَلِيٍّ ‏ ‏قَالَ ‏ ‏دَعَانِي أَبِي ‏ ‏عَلِيٌّ ‏ ‏بِوَضُوءٍ فَقَرَّبْتُهُ لَهُ ‏ ‏فَبَدَأَ فَغَسَلَ كَفَّيْهِ ثَلَاثَ مَرَّاتٍ قَبْلَ أَنْ يُدْخِلَهُمَا فِي وَضُوئِهِ ثُمَّ مَضْمَضَ ثَلَاثًا ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثَلَاثًا ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثَ مَرَّاتٍ ثُمَّ غَسَلَ يَدَهُ الْيُمْنَى إِلَى ‏ ‏الْمِرْفَقِ ‏ ‏ثَلَاثًا ثُمَّ الْيُسْرَى كَذَلِكَ ثُمَّ مَسَحَ بِرَأْسِهِ مَسْحَةً وَاحِدَةً ثُمَّ غَسَلَ رِجْلَهُ الْيُمْنَى إِلَى الْكَعْبَيْنِ ثَلَاثًا ثُمَّ الْيُسْرَى كَذَلِكَ ثُمَّ قَامَ قَائِمًا فَقَالَ نَاوِلْنِي فَنَاوَلْتُهُ الْإِنَاءَ الَّذِي فِيهِ ‏ ‏فَضْلُ ‏ ‏وَضُوئِهِ فَشَرِبَ مِنْ ‏ ‏فَضْلِ ‏ ‏وَضُوئِهِ قَائِمًا فَعَجِبْتُ فَلَمَّا رَآنِي قَالَ لَا تَعْجَبْ فَإِنِّي رَأَيْتُ أَبَاكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ مِثْلَ مَا رَأَيْتَنِي صَنَعْتُ يَقُولُ لِوُضُوئِهِ هَذَا وَشُرْبِ ‏ ‏فَضْلِ ‏ ‏وَضُوئِهِ قَائِمًا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0249def3-3c92-583c-bcd5-4a64b553b7ce', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '95', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ وَهُوَ ابْنُ قَيْسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏تَوَضَّأَ فَغَسَلَ كَفَّيْهِ حَتَّى أَنْقَاهُمَا ثُمَّ تَمَضْمَضَ ثَلَاثًا وَاسْتَنْشَقَ ثَلَاثًا وَغَسَلَ وَجْهَهُ ثَلَاثًا وَغَسَلَ ذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ مَسَحَ بِرَأْسِهِ ثُمَّ غَسَلَ قَدَمَيْهِ إِلَى الْكَعْبَيْنِ ثُمَّ قَامَ فَأَخَذَ ‏ ‏فَضْلَ ‏ ‏طَهُورِهِ فَشَرِبَ وَهُوَ قَائِمٌ ثُمَّ قَالَ أَحْبَبْتُ أَنْ أُرِيَكُمْ كَيْفَ طُهُورُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2b0a82c1-955d-5743-842e-4fcd4683e263', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '96', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏وَالْحَارِثُ بْنُ مِسْكِينٍ ‏ ‏قِرَاءَةً عَلَيْهِ وَأَنَا أَسْمَعُ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏عَنْ ‏ ‏ابْنِ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِعَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ جَدُّ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏هَلْ تَسْتَطِيعُ أَنْ تُرِيَنِي كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدٍ ‏ ‏نَعَمْ ‏ ‏فَدَعَا بِوَضُوءٍ فَأَفْرَغَ عَلَى يَدَيْهِ فَغَسَلَ يَدَيْهِ مَرَّتَيْنِ مَرَّتَيْنِ ثُمَّ تَمَضْمَضَ وَاسْتَنْشَقَ ثَلَاثًا ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا ثُمَّ غَسَلَ يَدَيْهِ مَرَّتَيْنِ مَرَّتَيْنِ إِلَى الْمِرْفَقَيْنِ ثُمَّ مَسَحَ رَأْسَهُ بِيَدَيْهِ فَأَقْبَلَ بِهِمَا وَأَدْبَرَ بَدَأَ بِمُقَدَّمِ رَأْسِهِ ثُمَّ ذَهَبَ بِهِمَا إِلَى قَفَاهُ ثُمَّ رَدَّهُمَا حَتَّى رَجَعَ إِلَى الْمَكَانِ الَّذِي بَدَأَ مِنْهُ ثُمَّ غَسَلَ رِجْلَيْهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dcd2787a-b82c-5120-84d4-8f579327d254', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '97', '‏ ‏أَخْبَرَنَا ‏ ‏عُتْبَةُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏مَالِكٍ هُوَ ابْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِعَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ ‏ ‏وَهُوَ جَدُّ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏هَلْ تَسْتَطِيعُ أَنْ تُرِيَنِي كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدٍ ‏ ‏نَعَمْ ‏ ‏فَدَعَا بِوَضُوءٍ فَأَفْرَغَ عَلَى يَدِهِ الْيُمْنَى فَغَسَلَ يَدَيْهِ مَرَّتَيْنِ ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ ثَلَاثًا ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا ثُمَّ غَسَلَ يَدَيْهِ مَرَّتَيْنِ مَرَّتَيْنِ إِلَى الْمِرْفَقَيْنِ ثُمَّ مَسَحَ رَأْسَهُ بِيَدَيْهِ فَأَقْبَلَ بِهِمَا وَأَدْبَرَ بَدَأَ بِمُقَدَّمِ رَأْسِهِ ثُمَّ ذَهَبَ بِهِمَا إِلَى قَفَاهُ ثُمَّ رَدَّهُمَا حَتَّى رَجَعَ إِلَى الْمَكَانِ الَّذِي بَدَأَ مِنْهُ ثُمَّ غَسَلَ رِجْلَيْهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2733bd84-c09b-5fcb-b456-2585a4cbdcbf', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '98', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏الَّذِي أُرِيَ النِّدَاءَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَغَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ مَرَّتَيْنِ وَغَسَلَ رِجْلَيْهِ مَرَّتَيْنِ وَمَسَحَ بِرَأْسِهِ مَرَّتَيْنِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('66514774-4d31-57a8-9218-171d503e5dbd', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '99', '‏ ‏أَخْبَرَنَا ‏ ‏الْحُسَيْنُ بْنُ حُرَيْثٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏جُعَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ مَرْوَانَ بْنِ الْحَارِثِ بْنِ أَبِي ذُنَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو عَبْدِ اللَّهِ سَالِمٌ سَبَلَانُ ‏ ‏قَالَ ‏ ‏وَكَانَتْ ‏ ‏عَائِشَةُ ‏ ‏تَسْتَعْجِبُ بِأَمَانَتِهِ وَتَسْتَأْجِرُهُ فَأَرَتْنِي كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏فَتَمَضْمَضَتْ ‏ ‏وَاسْتَنْثَرَتْ ‏ ‏ثَلَاثًا وَغَسَلَتْ وَجْهَهَا ثَلَاثًا ثُمَّ غَسَلَتْ يَدَهَا الْيُمْنَى ثَلَاثًا وَالْيُسْرَى ثَلَاثًا وَوَضَعَتْ يَدَهَا فِي مُقَدَّمِ رَأْسِهَا ثُمَّ مَسَحَتْ رَأْسَهَا مَسْحَةً وَاحِدَةً إِلَى مُؤَخِّرِهِ ثُمَّ أَمَرَّتْ يَدَهَا بِأُذُنَيْهَا ثُمَّ مَرَّتْ عَلَى الْخَدَّيْنِ ‏ ‏قَالَ ‏ ‏سَالِمٌ ‏ ‏كُنْتُ ‏ ‏آتِيهَا ‏ ‏مُكَاتَبًا ‏ ‏مَا ‏ ‏تَخْتَفِي مِنِّي فَتَجْلِسُ بَيْنَ يَدَيَّ وَتَتَحَدَّثُ مَعِي حَتَّى جِئْتُهَا ذَاتَ يَوْمٍ فَقُلْتُ ادْعِي لِي بِالْبَرَكَةِ يَا أُمَّ الْمُؤْمِنِينَ قَالَتْ وَمَا ذَاكَ قُلْتُ أَعْتَقَنِي اللَّهُ قَالَتْ بَارَكَ اللَّهُ لَكَ وَأَرْخَتْ الْحِجَابَ دُونِي فَلَمْ أَرَهَا بَعْدَ ذَلِكَ الْيَوْمِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b0c48564-81ee-5d4d-9ba2-73f2ddd3cd0e', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '100', '‏ ‏أَخْبَرَنَا ‏ ‏الْهَيْثَمُ بْنُ أَيُّوبَ الطَّالَقَانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَغَسَلَ يَدَيْهِ ثُمَّ تَمَضْمَضَ وَاسْتَنْشَقَ مِنْ غَرْفَةٍ وَاحِدَةٍ وَغَسَلَ وَجْهَهُ وَغَسَلَ يَدَيْهِ مَرَّةً مَرَّةً وَمَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ مَرَّةً ‏ ‏قَالَ ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏وَأَخْبَرَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏ابْنَ عَجْلَانَ ‏ ‏يَقُولُ ‏ ‏فِي ذَلِكَ وَغَسَلَ رِجْلَيْهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d34cd94c-96b6-5a1a-b2fb-07ce21a0b9f6', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '101', '‏ ‏أَخْبَرَنَا ‏ ‏مُجَاهِدُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَجْلَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تَوَضَّأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَغَرَفَ غَرْفَةً فَمَضْمَضَ وَاسْتَنْشَقَ ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ وَجْهَهُ ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ يَدَهُ الْيُمْنَى ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ يَدَهُ الْيُسْرَى ثُمَّ مَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ بَاطِنِهِمَا ‏ ‏بِالسَّبَّاحَتَيْنِ ‏ ‏وَظَاهِرِهِمَا بِإِبْهَامَيْهِ ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ رِجْلَهُ الْيُمْنَى ثُمَّ غَرَفَ غَرْفَةً فَغَسَلَ رِجْلَهُ الْيُسْرَى ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ee054832-fd1e-5284-8af3-387807f001d2', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '102', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏وَعُتْبَةُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الصُّنَابِحِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأَ الْعَبْدُ الْمُؤْمِنُ فَتَمَضْمَضَ خَرَجَتْ الْخَطَايَا مِنْ ‏ ‏فِيهِ ‏ ‏فَإِذَا ‏ ‏اسْتَنْثَرَ ‏ ‏خَرَجَتْ الْخَطَايَا مِنْ أَنْفِهِ فَإِذَا غَسَلَ وَجْهَهُ خَرَجْتِ الْخَطَايَا مِنْ وَجْهِهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ ‏ ‏أَشْفَارِ ‏ ‏عَيْنَيْهِ فَإِذَا غَسَلَ يَدَيْهِ خَرَجَتْ الْخَطَايَا مِنْ يَدَيْهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِ يَدَيْهِ فَإِذَا مَسَحَ بِرَأْسِهِ خَرَجَتْ الْخَطَايَا مِنْ رَأْسِهِ حَتَّى تَخْرُجَ مِنْ أُذُنَيْهِ فَإِذَا غَسَلَ رِجْلَيْهِ خَرَجَتْ الْخَطَايَا مِنْ رِجْلَيْهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِ رِجْلَيْهِ ثُمَّ كَانَ مَشْيُهُ إِلَى الْمَسْجِدِ وَصَلَاتُهُ نَافِلَةً لَهُ ‏ ‏قَالَ ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏الصُّنَابِحِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d46b1707-72c5-5bd6-8e67-17e5738a9e94', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '103', '‏ ‏أَخْبَرَنَا ‏ ‏الْحُسَيْنُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏ح ‏ ‏وَأَنْبَأَنَا ‏ ‏الْحُسَيْنُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عُجْرَةَ ‏ ‏عَنْ ‏ ‏بِلَالٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى الْخُفَّيْنِ ‏ ‏وَالْخِمَارِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('de7685bd-6393-5779-beb8-3800a4a81cf4', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '104', '‏ ‏و أَخْبَرَنَا ‏ ‏الْحُسَيْنُ بْنُ عَبْدِ الرَّحْمَنِ الْجَرْجَرَائِيُّ ‏ ‏عَنْ ‏ ‏طَلْقِ بْنِ غَنَّامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏وَحَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏الْبَرَاءِ بْنِ عَازِبٍ ‏ ‏عَنْ ‏ ‏بِلَالٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى الْخُفَّيْنِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e15b8e52-f9f4-57b0-bdb7-ba90c56db267', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '105', '‏ ‏أَخْبَرَنَا ‏ ‏هَنَّادُ بْنُ السَّرِيِّ ‏ ‏عَنْ ‏ ‏وَكِيعٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏بِلَالٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى ‏ ‏الْخِمَارِ ‏ ‏وَالْخُفَّيْنِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9c79219a-34ea-50da-be56-b768eff354a8', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '106', '‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عَبْدِ اللَّهِ الْمُزَنِيُّ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَمَسَحَ ‏ ‏نَاصِيَتَهُ ‏ ‏وَعِمَامَتَهُ وَعَلَى الْخُفَّيْنِ ‏ ‏قَالَ ‏ ‏بَكْرٌ ‏ ‏وَقَدْ ‏ ‏سَمِعْتُهُ مِنِ ‏ ‏ابْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('83b29096-ea16-55c7-8dc4-27ca2bb1db94', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '107', '‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏وَحُمَيْدُ بْنُ مَسْعَدَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ وَهُوَ ابْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عَبْدِ اللَّهِ الْمُزَنِيُّ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏تَخَلَّفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَخَلَّفْتُ مَعَهُ فَلَمَّا قَضَى حَاجَتَهُ قَالَ أَمَعَكَ مَاءٌ فَأَتَيْتُهُ ‏ ‏بِمِطْهَرَةٍ ‏ ‏فَغَسَلَ يَدَيْهِ وَغَسَلَ وَجْهَهُ ثُمَّ ذَهَبَ ‏ ‏يَحْسُرُ ‏ ‏عَنْ ذِرَاعَيْهِ فَضَاقَ كُمُّ ‏ ‏الْجُبَّةِ ‏ ‏فَأَلْقَاهُ عَلَى ‏ ‏مَنْكِبَيْهِ ‏ ‏فَغَسَلَ ذِرَاعَيْهِ وَمَسَحَ ‏ ‏بِنَاصِيَتِهِ ‏ ‏وَعَلَى الْعِمَامَةِ وَعَلَى خُفَّيْهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3bbbf9a7-a5f0-5b8e-b4ce-509cdabc4d3e', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '108', '‏ ‏أَخْبَرَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ وَهْبٍ الثَّقَفِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏قَالَ ‏ ‏خَصْلَتَانِ لَا أَسْأَلُ عَنْهُمَا أَحَدًا بَعْدَ مَا شَهِدْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كُنَّا مَعَهُ فِي سَفَرٍ فَبَرَزَ لِحَاجَتِهِ ثُمَّ ‏ ‏جَاءَ فَتَوَضَّأَ وَمَسَحَ ‏ ‏بِنَاصِيَتِهِ ‏ ‏وَجَانِبَيْ عِمَامَتِهِ وَمَسَحَ عَلَى خُفَّيْهِ قَالَ وَصَلَاةُ الْإِمَامِ خَلْفَ الرَّجُلِ مِنْ رَعِيَّتِهِ فَشَهِدْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ فِي سَفَرٍ فَحَضَرَتْ الصَّلَاةُ فَاحْتَبَسَ عَلَيْهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَقَامُوا الصَّلَاةَ وَقَدَّمُوا ‏ ‏ابْنَ عَوْفٍ ‏ ‏فَصَلَّى بِهِمْ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى خَلْفَ ‏ ‏ابْنِ عَوْفٍ ‏ ‏مَا بَقِيَ مِنْ الصَّلَاةِ فَلَمَّا سَلَّمَ ‏ ‏ابْنُ عَوْفٍ ‏ ‏قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَضَى مَا سُبِقَ بِهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c15d727e-4825-53e4-b53b-e4f072b3e446', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '109', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏ح ‏ ‏وَأَنْبَأَنَا ‏ ‏مُؤَمَّلُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْلٌ ‏ ‏لِلْعَقِبِ ‏ ‏مِنْ النَّارِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4b5f03d3-80f1-52f8-b2bc-41fd13e2467e', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '110', '‏ ‏أَخْبَرَنَا ‏ ‏مَحْمُودُ بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏ح ‏ ‏وَأَنْبَأَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَوْمًا يَتَوَضَّئُونَ فَرَأَى ‏ ‏أَعْقَابَهُمْ ‏ ‏تَلُوحُ فَقَالَ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('87502f76-5ff5-55d8-a0ee-a213473375fb', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '111', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْأَشْعَثُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏وَذَكَرَتْ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُحِبُّ التَّيَامُنَ مَا اسْتَطَاعَ فِي طُهُورِهِ وَنَعْلِهِ ‏ ‏وَتَرَجُّلِهِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏ثُمَّ سَمِعْتُ ‏ ‏الْأَشْعَثَ ‏ ‏بِوَاسِطٍ ‏ ‏يَقُولُ ‏ ‏يَحِبُّ التَّيَامُنَ فَذَكَرَ شَأْنَهُ كُلَّهُ ‏ ‏ثُمَّ ‏ ‏سَمِعْتُهُ ‏ ‏بِالْكُوفَةِ ‏ ‏يَقُولُ يُحِبُّ التَّيَامُنَ مَا اسْتَطَاعَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('37792fe7-c13c-5930-8470-529faf58e604', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '112', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو جَعْفَرٍ الْمَدَنِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُثْمَانَ بْنِ حُنَيْفٍ يَعْنِي عُمَارَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْقَيْسِيُّ ‏ ‏أَنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَأُتِيَ بِمَاءٍ ‏ ‏فَقَالَ ‏ ‏عَلَى يَدَيْهِ مِنْ الْإِنَاءِ فَغَسَلَهُمَا مَرَّةً وَغَسَلَ وَجْهَهُ وَذِرَاعَيْهِ مَرَّةً مَرَّةً وَغَسَلَ رِجْلَيْهِ بِيَمِينِهِ كِلْتَاهُمَا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6bd0a595-1c2f-5b54-b98f-40329327ec54', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '113', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ كَثِيرٍ ‏ ‏وَكَانَ يُكْنَى ‏ ‏أَبَا هَاشِمٍ ‏ ‏ح ‏ ‏وَأَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ لَقِيطٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأْتَ ‏ ‏فَأَسْبِغْ ‏ ‏الْوُضُوءَ ‏ ‏وَخَلِّلْ ‏ ‏بَيْنَ الْأَصَابِعِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('102db63e-c4f7-5d78-b4e9-42d655bc023a', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '114', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ آدَمَ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي زَائِدَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏وَغَيْرُهُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ الْوَادِعِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏تَوَضَّأَ فَغَسَلَ كَفَّيْهِ ثَلَاثًا وَتَمَضْمَضَ وَاسْتَنْشَقَ ثَلَاثًا وَغَسَلَ وَجْهَهُ ثَلَاثًا وَذِرَاعَيْهِ ثَلَاثًا ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَغَسَلَ رِجْلَيْهِ ثَلَاثًا ثَلَاثًا ثُمَّ قَالَ هَذَا وُضُوءُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e38e62a0-27ee-5b83-aac7-fe656df0d29b', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '115', '‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَمْرِو بْنِ السَّرْحِ ‏ ‏وَالْحَارِثُ بْنُ مِسْكِينٍ ‏ ‏قِرَاءَةً عَلَيْهِ وَأَنَا أَسْمَعُ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏عَنْ ‏ ‏ابْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عَطَاءَ بْنَ يَزِيدَ اللَّيْثِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏دَعَا بِوَضُوءٍ فَتَوَضَّأَ فَغَسَلَ كَفَّيْهِ ثَلَاثَ مَرَّاتٍ ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثَ مَرَّاتٍ ثُمَّ غَسَلَ يَدَهُ الْيُمْنَى إِلَى ‏ ‏الْمِرْفَقِ ‏ ‏ثَلَاثَ مَرَّاتٍ ثُمَّ غَسَلَ يَدَهُ الْيُسْرَى مِثْلَ ذَلِكَ ثُمَّ مَسَحَ بِرَأْسِهِ ثُمَّ غَسَلَ رِجْلَهُ الْيُمْنَى إِلَى ‏ ‏الْكَعْبَيْنِ ‏ ‏ثَلَاثَ مَرَّاتٍ ثُمَّ غَسَلَ رِجْلَهُ الْيُسْرَى مِثْلَ ذَلِكَ ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا ثُمَّ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا ثُمَّ قَامَ فَرَكَعَ رَكْعَتَيْنِ لَا يُحَدِّثُ فِيهِمَا نَفْسَهُ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8f8df488-82a3-5893-98ef-889f1bdb6b88', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '116', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏وَمَالِكٍ ‏ ‏وَابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏رَأَيْتُكَ تَلْبَسُ هَذِهِ ‏ ‏النِّعَالَ السِّبْتِيَّةَ ‏ ‏وَتَتَوَضَّأُ فِيهَا قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَلْبَسُهَا وَيَتَوَضَّأُ فِيهَا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bc982eec-6b33-587b-a2a4-9479f1472a0e', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '117', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَفْصٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ ‏ ‏تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ فَقِيلَ لَهُ أَتَمْسَحُ فَقَالَ قَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ ‏ ‏وَكَانَ أَصْحَابُ ‏ ‏عَبْدِ اللَّهِ ‏ ‏يُعْجِبُهُمْ قَوْلُ ‏ ‏جَرِيرٍ ‏ ‏وَكَانَ إِسْلَامُ ‏ ‏جَرِيرٍ ‏ ‏قَبْلَ مَوْتِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَسِيرٍ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('db621968-5181-521a-ae87-d7f2404c8416', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '118', '‏ ‏أَخْبَرَنَا ‏ ‏الْعَبَّاسُ بْنُ عَبْدِ الْعَظِيمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرْبُ بْنُ شَدَّادٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وَمَسَحَ عَلَى الْخُفَّيْنِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cd492086-dc60-52f5-903e-7158d699e5fd', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '119', '‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ دُحَيْمٌ ‏ ‏وَسُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏عَنْ ‏ ‏ابْنِ نَافِعٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِلَالٌ ‏ ‏الْأَسْوَاقَ فَذَهَبَ لِحَاجَتِهِ ثُمَّ خَرَجَ قَالَ ‏ ‏أُسَامَةُ ‏ ‏فَسَأَلْتُ ‏ ‏بِلَالًا ‏ ‏مَا صَنَعَ فَقَالَ ‏ ‏بِلَالٌ ‏ ‏ذَهَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَاجَتِهِ ثُمَّ تَوَضَّأَ فَغَسَلَ وَجْهَهُ وَيَدَيْهِ وَمَسَحَ بِرَأْسِهِ وَمَسَحَ عَلَى الْخُفَّيْنِ ثُمَّ صَلَّى ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0fbf9207-67a4-5581-b348-0fb549212a2b', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '120', '‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏وَالْحَارِثُ بْنُ مِسْكِينٍ ‏ ‏قِرَاءَةً عَلَيْهِ وَأَنَا أَسْمَعُ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏عَنْ ‏ ‏ابْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ مَسَحَ عَلَى الْخُفَّيْنِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('751de36d-9e2f-5c64-b8f3-fbdb6beb6983', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '121', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَعِيلُ وَهُوَ ابْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْحِ عَلَى الْخُفَّيْنِ أَنَّهُ لَا بَأْسَ بِهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3ce55ccb-2de6-58dc-998c-7a8af4d9766a', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '122', '‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ خَشْرَمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِيسَى ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَاجَتِهِ فَلَمَّا رَجَعَ تَلَقَّيْتُهُ ‏ ‏بِإِدَاوَةٍ ‏ ‏فَصَبَبْتُ عَلَيْهِ ‏ ‏فَغَسَلَ يَدَيْهِ ثُمَّ غَسَلَ وَجْهَهُ ثُمَّ ذَهَبَ لِيَغْسِلَ ذِرَاعَيْهِ فَضَاقَتْ بِهِ ‏ ‏الْجُبَّةُ ‏ ‏فَأَخْرَجَهُمَا مِنْ أَسْفَلِ ‏ ‏الْجُبَّةِ ‏ ‏فَغَسَلَهُمَا وَمَسَحَ عَلَى خُفَّيْهِ ثُمَّ صَلَّى بِنَا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('213358c8-c012-5264-9315-35389a56b4f3', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '123', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ خَرَجَ لِحَاجَتِهِ فَاتَّبَعَهُ ‏ ‏الْمُغِيرَةُ ‏ ‏بِإِدَاوَةٍ ‏ ‏فِيهَا مَاءٌ فَصَبَّ عَلَيْهِ حَتَّى فَرَغَ مِنْ حَاجَتِهِ ‏ ‏فَتَوَضَّأَ وَمَسَحَ عَلَى الْخُفَّيْنِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c0d9898c-414f-54ff-b19e-c947a8e47a03', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '124', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِسْمَعِيلَ بْنَ مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حَمْزَةَ بْنَ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَقَالَ تَخَلَّفْ يَا ‏ ‏مُغِيرَةُ ‏ ‏وَامْضُوا أَيُّهَا النَّاسُ فَتَخَلَّفْتُ وَمَعِي ‏ ‏إِدَاوَةٌ ‏ ‏مِنْ مَاءٍ وَمَضَى النَّاسُ فَذَهَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَاجَتِهِ فَلَمَّا رَجَعَ ذَهَبْتُ أَصُبُّ عَلَيْهِ وَعَلَيْهِ ‏ ‏جُبَّةٌ ‏ ‏رُومِيَّةٌ ضَيِّقَةُ الْكُمَّيْنِ فَأَرَادَ أَنْ يُخْرِجَ يَدَهُ مِنْهَا فَضَاقَتْ عَلَيْهِ فَأَخْرَجَ يَدَهُ مِنْ تَحْتِ ‏ ‏الْجُبَّةِ ‏ ‏فَغَسَلَ وَجْهَهُ وَيَدَيْهِ وَمَسَحَ بِرَأْسِهِ وَمَسَحَ عَلَى خُفَّيْهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ac67c79a-9bc6-51f2-bcc7-21c7108e9938', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '125', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي قَيْسٍ ‏ ‏عَنْ ‏ ‏هُذَيْلِ بْنِ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ عَلَى الْجَوْرَبَيْنِ وَالنَّعْلَيْنِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏مَا نَعْلَمُ أَحَدًا تَابَعَ ‏ ‏أَبَا قَيْسٍ ‏ ‏عَلَى هَذِهِ الرِّوَايَةِ وَالصَّحِيحُ عَنْ ‏ ‏الْمُغِيرَةِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ عَلَى الْخُفَّيْنِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ad39bbb7-4626-5a47-bef6-e1f5e895b8cc', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '126', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَسَّالٍ ‏ ‏قَالَ ‏ ‏رَخَّصَ لَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كُنَّا مُسَافِرِينَ أَنْ لَا نَنْزِعَ خِفَافَنَا ثَلَاثَةَ أَيَّامٍ ‏ ‏وَلَيَالِيَهُنَّ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1653749f-e099-536e-8958-fec5602be77b', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '127', '‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ سُلَيْمَانَ الرُّهَاوِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏وَمَالِكُ بْنُ مِغْوَلٍ ‏ ‏وَزُهَيْرٌ ‏ ‏وَأَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏وَسُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏صَفْوَانَ بْنَ عَسَّالٍ ‏ ‏عَنْ الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُنَا إِذَا كُنَّا مُسَافِرِينَ أَنْ نَمْسَحَ عَلَى خِفَافِنَا وَلَا نَنْزِعَهَا ثَلَاثَةَ أَيَّامٍ مِنْ غَائِطٍ وَبَوْلٍ وَنَوْمٍ إِلَّا مِنْ جَنَابَةٍ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1a390b80-26d0-591b-a725-10344b760dad', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '128', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ قَيْسٍ الْمُلَائِيِّ ‏ ‏عَنْ ‏ ‏الْحَكَمِ بْنِ عُتَيْبَةَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ هَانِئٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏جَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْمُسَافِرِ ثَلَاثَةَ أَيَّامٍ ‏ ‏وَلَيَالِيَهُنَّ وَيَوْمًا وَلَيْلَةً لِلْمُقِيمِ ‏ ‏يَعْنِي فِي الْمَسْحِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2bb91633-5fad-5e24-8080-3a3777ac3562', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '129', '‏ ‏أَخْبَرَنَا ‏ ‏هَنَّادُ بْنُ السَّرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُخَيْمِرَةَ ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ هَانِئٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏عَنْ الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَالَتْ ائْتِ ‏ ‏عَلِيًّا ‏ ‏فَإِنَّهُ أَعْلَمُ بِذَلِكَ مِنِّي فَأَتَيْتُ ‏ ‏عَلِيًّا ‏ ‏فَسَأَلْتُهُ عَنْ الْمَسْحِ فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُنَا أَنْ يَمْسَحَ الْمُقِيمُ يَوْمًا وَلَيْلَةً وَالْمُسَافِرُ ثَلَاثًا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c10cb79f-a51e-5537-9dd7-c8ef38bb287d', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '130', '‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ مَيْسَرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النَّزَّالَ بْنَ سَبْرَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏صَلَّى الظُّهْرَ ثُمَّ قَعَدَ لِحَوَائِجِ النَّاسِ فَلَمَّا حَضَرَتْ الْعَصْرُ ‏ ‏أُتِيَ ‏ ‏بِتَوْرٍ ‏ ‏مِنْ مَاءٍ فَأَخَذَ مِنْهُ كَفًّا فَمَسَحَ بِهِ وَجْهَهُ وَذِرَاعَيْهِ وَرَأْسَهُ وَرِجْلَيْهِ ثُمَّ أَخَذَ ‏ ‏فَضْلَهُ ‏ ‏فَشَرِبَ قَائِمًا وَقَالَ إِنَّ نَاسًا يَكْرَهُونَ هَذَا وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ وَهَذَا وُضُوءُ مَنْ لَمْ يُحْدِثْ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('087a8893-8a76-524d-a908-2d9218ff02fe', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '131', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّهُ ذَكَرَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِإِنَاءٍ صَغِيرٍ فَتَوَضَّأَ قُلْتُ أَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ لِكُلِّ صَلَاةٍ قَالَ نَعَمْ قَالَ فَأَنْتُمْ قَالَ كُنَّا نُصَلِّي الصَّلَوَاتِ مَا لَمْ نُحْدِثْ قَالَ وَقَدْ كُنَّا نُصَلِّي الصَّلَوَاتِ بِوُضُوءٍ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('06d9b7cb-0cd9-5f7c-ab8f-6cd8d85bdfe5', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '132', '‏ ‏أَخْبَرَنَا ‏ ‏زِيَادُ بْنُ أَيَّوبَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عُلَيَّةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ مِنْ الْخَلَاءِ فَقُرِّبَ إِلَيْهِ طَعَامٌ فَقَالُوا أَلَا ‏ ‏نَأْتِيكَ بِوَضُوءٍ فَقَالَ ‏ ‏إِنَّمَا أُمِرْتُ بِالْوُضُوءِ إِذَا قُمْتُ إِلَى الصَّلَاةِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fc415216-94a0-5634-8e41-3720e2273337', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '133', '‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلْقَمَةُ بْنُ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ لِكُلِّ صَلَاةٍ فَلَمَّا كَانَ يَوْمُ الْفَتْحِ صَلَّى الصَّلَوَاتِ بِوُضُوءٍ وَاحِدٍ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏فَعَلْتَ شَيْئًا لَمْ تَكُنْ تَفْعَلُهُ قَالَ عَمْدًا فَعَلْتُهُ يَا ‏ ‏عُمَرُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ddb24e2c-0de1-5a08-a86d-65f9405a62b9', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '134', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَعِيلُ بْنُ مَسْعُودٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدُ بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا تَوَضَّأَ أَخَذَ حَفْنَةً مِنْ مَاءٍ فَقَالَ بِهَا هَكَذَا وَوَصَفَ ‏ ‏شُعْبَةُ ‏ ‏نَضَحَ ‏ ‏بِهِ فَرْجَهُ ‏ ‏فَذَكَرْتُهُ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏فَأَعْجَبَهُ ‏ ‏قَالَ الشَّيْخُ ‏ ‏ابْنُ السُّنِّيِّ ‏ ‏الْحَكَمُ هُوَ ابْنُ سُفْيَانَ الثَّقَفِيُّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('37e57762-5ecd-56c3-a299-b245c5b04d76', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '135', '‏ ‏أَخْبَرَنَا ‏ ‏الْعَبَّاسُ بْنُ مُحَمَّدٍ الدُّورِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَحْوَصُ بْنُ جَوَّابٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ رُزَيْقٍ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏ح ‏ ‏وَأَنْبَأَنَا ‏ ‏أَحْمَدُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَاسِمٌ وَهُوَ ابْنُ يَزِيدَ الْجَرْمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏الْحَكَمِ بْنِ سُفْيَانَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ‏ ‏وَنَضَحَ ‏ ‏فَرْجَهُ ‏ ‏قَالَ ‏ ‏أَحْمَدُ ‏ ‏فَنَضَحَ ‏ ‏فَرْجَهُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eef44c2e-9fcd-5839-9bc0-90b09301bb91', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '136', '‏ ‏أَخْبَرَنَا ‏ ‏أَبُو دَاوُدَ سُلَيْمَانُ بْنُ سَيْفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَتَّابٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَلِيًّا ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏تَوَضَّأَ ثَلَاثًا ثَلَاثًا ثُمَّ قَامَ فَشَرِبَ ‏ ‏فَضْلَ ‏ ‏وَضُوئِهِ وَقَالَ صَنَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا صَنَعْتُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('703e9a45-08a1-5906-bbd1-5c0fe8f7c483', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '137', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏عَونِ بْنِ أَبِي جُحَيْفَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏وَأَخْرَجَ ‏ ‏بِلَالٌ ‏ ‏فَضْلَ ‏ ‏وَضُوئِهِ ‏ ‏فَابْتَدَرَهُ ‏ ‏النَّاسُ فَنِلْتُ مِنْهُ شَيْئًا وَرَكَزْتُ لَهُ ‏ ‏الْعَنَزَةَ ‏ ‏فَصَلَّى بِالنَّاسِ وَالْحُمُرُ وَالْكِلَابُ وَالْمَرْأَةُ يَمُرُّونَ بَيْنَ يَدَيْهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e7db6448-e19d-5198-9ec9-617d2f37d342', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '138', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ الْمُنْكَدِرِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏يَقُولُ ‏ ‏مَرِضْتُ فَأَتَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏يَعُودَانِي ‏ ‏فَوَجَدَانِي قَدْ أُغْمِيَ عَلَيَّ فَتَوَضَّأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَبَّ عَلَيَّ وَضُوءَهُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('07a309d6-ea8f-5195-a435-a5b8c057ea4e', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '139', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقْبَلُ اللَّهُ صَلَاةً بِغَيْرِ طُهُورٍ وَلَا صَدَقَةً مِنْ ‏ ‏غُلُولٍ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c1ea9491-8925-526f-b2d3-259c5ae3a056', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '140', '‏ ‏أَخْبَرَنَا ‏ ‏مَحْمُودُ بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عَائِشَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْأَلُهُ عَنْ الْوُضُوءِ ‏ ‏فَأَرَاهُ الْوُضُوءَ ثَلَاثًا ثَلَاثًا ثُمَّ قَالَ هَكَذَا الْوُضُوءُ فَمَنْ زَادَ عَلَى هَذَا فَقَدْ أَسَاءَ وَتَعَدَّى وَظَلَمَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1654cff3-0459-5299-9af9-c92ac43f43b9', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '141', '‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَبِيبِ بْنِ عَرَبِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو جَهْضَمٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُبَيْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏فَقَالَ وَاللَّهِ مَا خَصَّنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَيْءٍ دُونَ النَّاسِ إِلَّا بِثَلَاثَةِ أَشْيَاءَ فَإِنَّهُ ‏ ‏أَمَرَنَا أَنْ ‏ ‏نُسْبِغَ ‏ ‏الْوُضُوءَ وَلَا نَأْكُلَ الصَّدَقَةَ وَلَا نُنْزِيَ الْحُمُرَ عَلَى الْخَيْلِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7b86c7b8-c3be-5b5a-a942-6a3cf8409aff', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '142', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ قَال رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cea47619-9b1a-5726-929a-417dee9d6a59', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '143', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِمَا يَمْحُو اللَّهُ بِهِ الْخَطَايَا وَيَرْفَعُ بِهِ الدَّرَجَاتِ ‏ ‏إِسْبَاغُ ‏ ‏الْوُضُوءِ عَلَى الْمَكَارِهِ وَكَثْرَةُ ‏ ‏الْخُطَا إِلَى الْمَسَاجِدِ وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ فَذَلِكُمْ ‏ ‏الرِّبَاطُ ‏ ‏فَذَلِكُمْ ‏ ‏الرِّبَاطُ ‏ ‏فَذَلِكُمْ ‏ ‏الرِّبَاطُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('014df32f-2918-5ceb-9aa4-6cd44af68f34', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '144', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ سُفْيَانَ الثَّقَفِيِّ ‏ ‏أَنَّهُمْ غَزَوْا ‏ ‏غَزْوَةَ السُّلَاسِلِ ‏ ‏فَفَاتَهُمْ الْغَزْوُ فَرَابَطُوا ثُمَّ رَجَعُوا إِلَى ‏ ‏مُعَاوِيَةَ ‏ ‏وَعِنْدَهُ ‏ ‏أَبُو أَيُّوبَ ‏ ‏وَعُقْبَةُ بْنُ عَامِرٍ ‏ ‏فَقَالَ ‏ ‏عَاصِمٌ ‏ ‏يَا ‏ ‏أَبَا أَيُّوبَ ‏ ‏فَاتَنَا الْغَزْوُ الْعَامَ وَقَدْ أُخْبِرْنَا أَنَّهُ مَنْ صَلَّى فِي الْمَسَاجِدِ الْأَرْبَعَةِ غُفِرَ لَهُ ذَنْبُهُ فَقَالَ يَا ابْنَ أَخِي أَدُلُّكَ عَلَى أَيْسَرَ مِنْ ذَلِكَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَوَضَّأَ كَمَا أُمِرَ وَصَلَّى كَمَا أُمِرَ غُفِرَ لَهُ مَا قَدَّمَ مِنْ عَمَلٍ ‏ ‏أَكَذَلِكَ يَا ‏ ‏عُقْبَةُ ‏ ‏قَالَ نَعَمْ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('70349583-139e-5971-b53d-d39148c6ed6b', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '145', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمْرَانَ بْنَ أَبَانَ ‏ ‏أَخْبَرَ ‏ ‏أَبَا بُرْدَةَ ‏ ‏فِي الْمَسْجِدِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُثْمَانَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَتَمَّ الْوُضُوءَ كَمَا أَمَرَهُ اللَّهُ عَزَّ وَجَلَّ فَالصَّلَوَاتُ الْخَمْسُ كَفَّارَاتٌ لِمَا بَيْنَهُنَّ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a00a3b69-1ac8-58c7-9082-bb427934d2d1', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '146', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ امْرِئٍ يَتَوَضَّأُ فَيُحْسِنُ وُضُوءَهُ ثُمَّ ‏ ‏يُصَلِّي الصَّلَاةَ إِلَّا غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الصَّلَاةِ الْأُخْرَى حَتَّى يُصَلِّيَهَا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7cb1d3f3-1cfd-591c-9a2d-2c82934e55cf', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '147', '‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ مَنْصُورٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏آدَمُ بْنُ أَبِي إِيَاسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ هُوَ ابْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو يَحْيَى سُلَيْمُ بْنُ عَامِرٍ ‏ ‏وَضَمْرَةُ بْنُ حَبِيبٍ ‏ ‏وَأَبُو طَلْحَةَ نُعَيْمُ بْنُ زِيَادٍ ‏ ‏قَالُوا سَمِعْنَا ‏ ‏أَبَا أُمَامَةَ الْبَاهِلِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَمْرَو بْنَ عَبَسَةَ ‏ ‏يَقُولُ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ الْوُضُوءُ قَالَ أَمَّا الْوُضُوءُ فَإِنَّكَ ‏ ‏إِذَا تَوَضَّأْتَ فَغَسَلْتَ كَفَّيْكَ فَأَنْقَيْتَهُمَا خَرَجَتْ خَطَايَاكَ مِنْ بَيْنِ أَظْفَارِكَ وَأَنَامِلِكَ فَإِذَا مَضْمَضْتَ وَاسْتَنْشَقْتَ مَنْخِرَيْكَ وَغَسَلْتَ وَجْهَكَ وَيَدَيْكَ إِلَى الْمِرْفَقَيْنِ وَمَسَحْتَ رَأْسَكَ وَغَسَلْتَ رِجْلَيْكَ إِلَى ‏ ‏الْكَعْبَيْنِ ‏ ‏اغْتَسَلْتَ مِنْ عَامَّةِ خَطَايَاكَ فَإِنْ أَنْتَ وَضَعْتَ وَجْهَكَ لِلَّهِ عَزَّ وَجَلَّ خَرَجْتَ مِنْ خَطَايَاكَ كَيَوْمَ وَلَدَتْكَ أُمُّكَ ‏ ‏قَالَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏فَقُلْتُ يَا ‏ ‏عَمْرَو بْنَ عَبَسَةَ ‏ ‏انْظُرْ مَا تَقُولُ أَكُلُّ هَذَا يُعْطَى فِي مَجْلِسٍ وَاحِدٍ فَقَالَ أَمَا وَاللَّهِ لَقَدْ كَبِرَتْ سِنِّي وَدَنَا أَجَلِي وَمَا بِي مِنْ فَقْرٍ فَأَكْذِبَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَقَدْ سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a8b39784-e1b1-5cd0-85f7-a615e44fda0a', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '148', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَلِيِّ بْنِ حَرْبٍ الْمَرْوَزِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْخَوْلَانِيِّ ‏ ‏وَأَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ قَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ فُتِّحَتْ لَهُ ثَمَانِيَةُ أَبْوَابِ الْجَنَّةِ يَدْخُلُ مِنْ أَيِّهَا شَاءَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7c1e01eb-f065-5b86-99df-f75ec6965622', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '149', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏خَلَفٍ وَهُوَ ابْنُ خَلِيفَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَالِكٍ الْأَشْجَعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏قَالَ ‏ ‏كُنْتُ خَلْفَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَهُوَ يَتَوَضَّأُ لِلصَّلَاةِ وَكَانَ يَغْسِلُ يَدَيْهِ حَتَّى يَبْلُغَ إِبْطَيْهِ فَقُلْتُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏مَا هَذَا الْوُضُوءُ فَقَالَ لِي يَا بَنِي ‏ ‏فَرُّوخَ ‏ ‏أَنْتُمْ هَاهُنَا لَوْ عَلِمْتُ أَنَّكُمْ هَاهُنَا مَا تَوَضَّأْتُ هَذَا الْوُضُوءَ سَمِعْتُ خَلِيلِي ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَبْلُغُ ‏ ‏حِلْيَةُ ‏ ‏الْمُؤْمِنِ حَيْثُ يَبْلُغُ الْوُضُوءُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('775cdb9f-9c3a-5e8d-a632-be65b096045c', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '150', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى الْمَقْبُرَةِ فَقَالَ ‏ ‏السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ وَدِدْتُ أَنِّي قَدْ رَأَيْتُ إِخْوَانَنَا قَالُوا يَا رَسُولَ اللَّهِ أَلَسْنَا إِخْوَانَكَ قَالَ بَلْ أَنْتُمْ أَصْحَابِي وَإِخْوَانِي الَّذِينَ لَمْ يَأْتُوا بَعْدُ وَأَنَا ‏ ‏فَرَطُهُمْ ‏ ‏عَلَى الْحَوْضِ قَالُوا يَا رَسُولَ اللَّهِ كَيْفَ تَعْرِفُ مَنْ يَأْتِي بَعْدَكَ مِنْ أُمَّتِكَ قَالَ أَرَأَيْتَ لَوْ كَانَ لِرَجُلٍ خَيْلٌ ‏ ‏غُرٌّ ‏ ‏مُحَجَّلَةٌ ‏ ‏فِي خَيْلٍ ‏ ‏بُهْمٍ دُهْمٍ ‏ ‏أَلَا يَعْرِفُ خَيْلَهُ قَالُوا بَلَى قَالَ فَإِنَّهُمْ يَأْتُونَ يَوْمَ الْقِيَامَةِ ‏ ‏غُرًّا ‏ ‏مُحَجَّلِينَ ‏ ‏مِنْ الْوُضُوءِ وَأَنَا ‏ ‏فَرَطُهُمْ ‏ ‏عَلَى الْحَوْضِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8ae8f2c8-a917-568a-b6ea-f178220464cb', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '151', '‏ ‏أَخْبَرَنَا ‏ ‏مُوسَى بْنُ عَبْدِ الرَّحْمَنِ الْمَسْرُوقِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رَبِيعَةُ بْنُ يَزِيدَ الدِّمَشْقِيُّ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْخَوْلَانِيِّ ‏ ‏وَأَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ صَلَّى رَكْعَتَيْنِ يُقْبِلُ عَلَيْهِمَا بِقَلْبِهِ وَوَجْهِهِ وَجَبَتْ لَهُ الْجَنَّةُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('822333bd-05ff-5957-af54-07455080253a', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '152', '‏ ‏أَخْبَرَنَا ‏ ‏هَنَّادُ بْنُ السَّرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏كُنْتُ رَجُلًا ‏ ‏مَذَّاءً ‏ ‏وَكَانَتْ ابْنَةُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَحْتِي فَاسْتَحْيَيْتُ أَنْ أَسْأَلَهُ فَقُلْتُ لِرَجُلٍ جَالِسٍ إِلَى جَنْبِي سَلْهُ فَسَأَلَهُ فَقَالَ ‏ ‏فِيهِ الْوُضُوءُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('aa6967e5-953b-5d0e-a453-3806a3ce4a9c', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '153', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِلْمِقْدَادِ ‏ ‏إِذَا ‏ ‏بَنَى ‏ ‏الرَّجُلُ بِأَهْلِهِ فَأَمْذَى وَلَمْ يُجَامِعْ فَسَلْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَإِنِّي أَسْتَحِي أَنْ أَسْأَلَهُ عَنْ ذَلِكَ وَابْنَتُهُ تَحْتِي فَسَأَلَهُ فَقَالَ ‏ ‏يَغْسِلُ مَذَاكِيرَهُ وَيَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fd5cfb1c-0898-5a04-8bd0-618563bde7e6', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '154', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشِ بْنِ أَنَسٍ ‏ ‏أَنَّ ‏ ‏عَلِيًا ‏ ‏قَالَ ‏ ‏كُنْتُ رَجُلًا ‏ ‏مَذَّاءً ‏ ‏فَأَمَرْتُ ‏ ‏عَمَّارَ بْنَ يَاسِرٍ ‏ ‏يَسْأَلُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَجْلِ ابْنَتِهِ عِنْدِي فَقَالَ ‏ ‏يَكْفِي مِنْ ذَلِكَ الْوُضُوءُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('24b8b7b5-e82f-5ef4-92fc-93d7cbee38a3', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '155', '‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏أُمَيَّةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏أَنَّ ‏ ‏رَوْحَ بْنَ الْقَاسِمِ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏ابْنِ أَبِي نُجَيْحٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ خَلِيفَةَ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏أَمَرَ ‏ ‏عَمَّارًا ‏ ‏أَنْ يَسْأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمَذْيِ ‏ ‏فَقَالَ ‏ ‏يَغْسِلُ مَذَاكِيرَهُ وَيَتَوَضَّأُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('009df313-18ce-51c2-a3af-3d36c0fab5ab', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '156', '‏ ‏أَخْبَرَنَا ‏ ‏عُتْبَةُ بْنُ عَبْدِ اللَّهِ الْمَرْوَزِيُّ ‏ ‏عَنْ ‏ ‏مَالِكٍ وَهُوَ ابْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏الْمِقْدَادِ بْنِ الْأَسْوَدِ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏أَمَرَهُ أَنْ يَسْأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الرَّجُلِ إِذَا دَنَا مِنْ أَهْلِهِ فَخَرَجَ مِنْهُ ‏ ‏الْمَذْيُ ‏ ‏مَاذَا عَلَيْهِ فَإِنَّ عِنْدِي ابْنَتَهُ وَأَنَا أَسْتَحِي أَنْ أَسْأَلَهُ فَسَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ فَقَالَ ‏ ‏إِذَا وَجَدَ أَحَدُكُمْ ذَلِكَ ‏ ‏فَلْيَنْضَحْ ‏ ‏فَرْجَهُ وَيَتَوَضَّأْ وُضُوءَهُ لِلصَّلَاةِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d4dd5a0b-7b44-565d-b51d-0f7f1ca26109', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '157', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْأَعَلَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سُلَيْمَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُنْذِرًا ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏اسْتَحْيَيْتُ أَنْ أَسْأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمَذْيِ ‏ ‏مِنْ أَجْلِ ‏ ‏فَاطِمَةَ ‏ ‏فَأَمَرْتُ ‏ ‏الْمِقْدَادَ بْنَ الْأَسْوَدِ ‏ ‏فَسَأَلَهُ فَقَالَ ‏ ‏فِيهِ الْوُضُوءُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('17fd5356-5c6d-57a8-91bd-7b3fb265e804', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '158', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏زِرَّ بْنَ حُبَيْشٍ ‏ ‏يُحَدِّثُ قَالَ ‏ ‏أَتَيْتُ رَجُلًا يُدْعَى ‏ ‏صَفْوَانَ بْنَ عَسَّالٍ ‏ ‏فَقَعَدْتُ عَلَى بَابِهِ فَخَرَجَ فَقَالَ مَا شَأْنُكَ قُلْتُ أَطْلُبُ الْعِلْمَ قَالَ إِنَّ الْمَلَائِكَةَ تَضَعُ أَجْنِحَتَهَا لِطَالِبِ الْعِلْمِ رِضًا بِمَا يَطْلُبُ فَقَالَ عَنْ أَيِّ شَيْءٍ تَسْأَلُ قُلْتُ عَنْ الْخُفَّيْنِ قَالَ كُنَّا إِذَا كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ‏ ‏أَمَرَنَا أَنْ لَا نَنْزِعَهُ ثَلَاثًا إِلَّا مِنْ جَنَابَةٍ وَلَكِنْ مِنْ غَائِطٍ وَبَوْلٍ وَنَوْمٍ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4cb83ea6-1a70-577a-a2cf-a7535d01c1db', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '159', '‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏وَإِسْمَعِيلُ بْنُ مَسْعُودٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏صَفْوَانُ بْنُ عَسَّالٍ ‏ ‏كُنَّا إِذَا كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ‏ ‏أَمَرَنَا أَنْ لَا نَنْزِعَهُ ثَلَاثًا إِلَّا مِنْ جَنَابَةٍ وَلَكِنْ مِنْ غَائِطٍ وَبَوْلٍ وَنَوْمٍ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9534009b-dad2-599e-bae2-d3a7eba574d6', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '160', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏ح ‏ ‏و أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدٌ يَعْنِي ابْنَ الْمُسَيَّبِ ‏ ‏وَعَبَّادُ بْنُ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ وَهُوَ ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدٍ ‏ ‏قَالَ ‏ ‏شُكِيَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّجُلُ يَجِدُ الشَّيْءَ فِي الصَّلَاةِ قَالَ ‏ ‏لَا يَنْصَرِفْ حَتَّى يَجِدَ رِيحًا أَوْ يَسْمَعَ صَوْتًا ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('276797a0-1bde-51e4-9651-c2a8556e5d2e', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '161', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَعِيلُ بْنُ مَسْعُودٍ ‏ ‏وَحُمَيْدُ بْنُ مَسْعَدَةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ مَنَامِهِ فَلَا يُدْخِلْ يَدَهُ فِي الْإِنَاءِ حَتَّى يُفْرِغَ عَلَيْهَا ثَلَاثَ مَرَّاتٍ فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('42a167e1-cb90-51da-9c57-b70a23ecb95a', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '162', '‏ ‏أَخْبَرَنَا ‏ ‏بِشْرُ بْنُ هِلَالٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نَعَسَ الرَّجُلُ وَهُوَ فِي الصَّلَاةِ فَلْيَنْصَرِفْ لَعَلَّهُ يَدْعُو عَلَى نَفْسِهِ وَهُوَ لَا يَدْرِي ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c03d643b-77e5-58a0-9cc5-407073248342', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '163', '‏ ‏أَخْبَرَنَا ‏ ‏هَارُونُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْنٌ ‏ ‏أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏ح ‏ ‏وَالْحَارِثُ بْنُ مِسْكِينٍ ‏ ‏قِرَاءَةً عَلَيْهِ وَأَنَا أَسْمَعُ عَنْ ‏ ‏ابْنِ الْقَاسِمِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏يَقُولُ دَخَلْتُ عَلَى ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏فَذَكَرْنَا مَا يَكُونُ مِنْهُ الْوُضُوءُ فَقَالَ ‏ ‏مَرْوَانُ ‏ ‏مِنْ مَسِّ الذَّكَرِ الْوُضُوءُ فَقَالَ ‏ ‏عُرْوَةُ ‏ ‏مَا عَلِمْتُ ذَلِكَ ‏ ‏فَقَالَ ‏ ‏مَرْوَانُ ‏ ‏أَخْبَرَتْنِي ‏ ‏بُسْرَةُ بِنْتُ صَفْوَانَ ‏ ‏أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا مَسَّ أَحَدُكُمْ ذَكَرَهُ فَلْيَتَوَضَّأْ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('747db085-b993-5e47-9cc8-2a372bb70b44', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '164', '‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ مُحَمَّدِ بْنِ الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعَيْبٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏يَقُولُ ‏ ‏ذَكَرَ ‏ ‏مَرْوَانُ ‏ ‏فِي إِمَارَتِهِ عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏أَنَّهُ يُتَوَضَّأُ مِنْ مَسِّ الذَّكَرِ إِذَا أَفْضَى إِلَيْهِ الرَّجُلُ بِيَدِهِ فَأَنْكَرْتُ ذَلِكَ وَقُلْتُ لَا وُضُوءَ عَلَى مَنْ مَسَّهُ ‏ ‏فَقَالَ ‏ ‏مَرْوَانُ ‏ ‏أَخْبَرَتْنِي ‏ ‏بُسْرَةُ بِنْتُ صَفْوَانَ ‏ ‏أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ مَا يُتَوَضَّأُ مِنْهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيُتَوَضَّأُ مِنْ مَسِّ الذَّكَرِ ‏ ‏قَالَ ‏ ‏عُرْوَةُ ‏ ‏فَلَمْ أَزَلْ ‏ ‏أُمَارِي ‏ ‏مَرْوَانَ ‏ ‏حَتَّى دَعَا ‏ ‏رَجُلًا ‏ ‏مِنْ حَرَسِهِ ‏ ‏فَأَرْسَلَهُ إِلَى ‏ ‏بُسْرَةَ ‏ ‏فَسَأَلَهَا عَمَّا حَدَّثَتْ ‏ ‏مَرْوَانَ ‏ ‏فَأَرْسَلَتْ إِلَيْهِ ‏ ‏بُسْرَةُ ‏ ‏بِمِثْلِ الَّذِي حَدَّثَنِي عَنْهَا ‏ ‏مَرْوَانُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('56b4f68a-5e58-5e3d-a105-7665decc0d2c', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '165', '‏ ‏أَخْبَرَنَا ‏ ‏هَنَّادٌ ‏ ‏عَنْ ‏ ‏مُلَازِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَدْرٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏خَرَجْنَا وَفْدًا حَتَّى قَدِمْنَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَايَعْنَاهُ وَصَلَّيْنَا مَعَهُ فَلَمَّا قَضَى الصَّلَاةَ جَاءَ رَجُلٌ كَأَنَّهُ ‏ ‏بَدَوِيٌّ فَقَالَ يَا رَسُولَ اللَّهِ مَا ‏ ‏تَرَى فِي رَجُلٍ مَسَّ ذَكَرَهُ فِي الصَّلَاةِ قَالَ ‏ ‏وَهَلْ هُوَ إِلَّا ‏ ‏مُضْغَةٌ ‏ ‏مِنْكَ أَوْ ‏ ‏بَضْعَةٌ ‏ ‏مِنْكَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7cbc1d31-c6fc-52e9-9453-746fa3fa2178', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '166', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏شُعَيْبٍ ‏ ‏عَنْ ‏ ‏اللَّيْثِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُصَلِّي وَإِنِّي لَمُعْتَرِضَةٌ بَيْنَ يَدَيْهِ اعْتِرَاضَ الْجَنَازَةِ حَتَّى إِذَا أَرَادَ أَنْ يُوتِرَ مَسَّنِي بِرِجْلِهِ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('63ecec36-1610-591c-92e1-b37a04a7e05c', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '167', '‏ ‏أَخْبَرَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ بْنَ مُحَمَّدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَقَدْ رَأَيْتُمُونِي مُعْتَرِضَةً بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فَإِذَا أَرَادَ أَنْ يَسْجُدَ ‏ ‏غَمَزَ ‏ ‏رِجْلِي فَضَمَمْتُهَا إِلَيَّ ثُمَّ يَسْجُدُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('494d22d7-ad8c-55ee-8672-07bc6b1425b3', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '168', '‏ ‏أَخْبَرَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَنَامُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرِجْلَايَ فِي قِبْلَتِهِ فَإِذَا سَجَدَ ‏ ‏غَمَزَنِي ‏ ‏فَقَبَضْتُ رِجْلَيَّ فَإِذَا قَامَ بَسَطْتُهُمَا وَالْبُيُوتُ يَوْمِئِذٍ لَيْسَ فِيهَا مَصَابِيحُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('39730f0d-abb1-5ffb-9c18-b327f4b27a0b', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '169', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الْمُبَارَكِ ‏ ‏وَنُصَيْرُ بْنُ الْفَرَجِ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏فَقَدْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَجَعَلْتُ أَطْلُبُهُ بِيَدِي فَوَقَعَتْ يَدِي عَلَى قَدَمَيْهِ وَهُمَا مَنْصُوبَتَانِ وَهُوَ سَاجِدٌ يَقُولُ ‏ ‏أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ وَأَعُوذُ بِكَ مِنْكَ لَا أُحْصِي ثَنَاءً عَلَيْكَ أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c1883411-a16c-5e58-9e53-32152293f01b', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '170', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو رَوْقٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَبِّلُ بَعْضَ أَزْوَاجِهِ ثُمَّ ‏ ‏يُصَلِّي وَلَا يَتَوَضَّأُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏لَيْسَ فِي هَذَا الْبَابِ حَدِيثٌ أَحْسَنُ مِنْ هَذَا الْحَدِيثِ ‏ ‏وَإِنْ كَانَ مُرْسَلًا ‏ ‏وَقَدْ رَوَى هَذَا الْحَدِيثَ ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏يَحْيَى الْقَطَّانُ ‏ ‏حَدِيثُ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏هَذَا ‏ ‏وَحَدِيثُ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏تُصَلِّ وَإِنْ قَطَرَ الدَّمُ عَلَى الْحَصِيرِ لَا شَيْءَ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2fba10e3-924c-55d0-a53f-2acde89962da', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '171', '‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('91f0d215-c793-5016-8dbf-3e926a2635ef', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '172', '‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ حَرْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّبَيْدِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ قَارِظٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('90830033-ee3d-5c10-9011-05fc2c4597ea', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '173', '‏ ‏أَخْبَرَنَا ‏ ‏الرَّبِيعُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ بَكْرٍ وَهُوَ ابْنُ مُضَرَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ سَوَادَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ إِبْرَاهِيمَ بْنِ قَارِظٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَتَوَضَّأُ عَلَى ظَهْرِ الْمَسْجِدِ فَقَالَ أَكَلْتُ ‏ ‏أَثْوَارَ ‏ ‏أَقِطٍ ‏ ‏فَتَوَضَّأْتُ مِنْهَا إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُ بِالْوُضُوءِ مِمَّا مَسَّتْ النَّارُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4d35cb5e-67c1-5ada-b2b0-8b0c099bb6f3', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '174', '‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ يَعْقُوبَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏حُسَيْنٍ الْمُعَلِّمِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَىَ بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَمْرٍو الْأَوْزَاعِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏الْمُطَّلِبَ بْنَ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏يَقُولُ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَتَوَضَّأُ مِنْ طَعَامٍ أَجِدُهُ فِي كِتَابِ اللَّهِ حَلَالًا لِأَنَّ النَّارَ مَسَّتْهُ فَجَمَعَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏حَصًى فَقَالَ أَشْهَدُ عَدَدَ هَذَا الْحَصَى أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4d2d429d-c118-57db-a1ca-d1a4f649a569', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '175', '‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ جَعْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرٍو ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ee891c85-1c19-5b0c-bfd1-1e8ee9a19c15', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '176', '‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَلِيٍّ ‏ ‏وَمُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَا أَنْبَأَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ جَعْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏الْقَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّئُوا مِمَّا غَيَّرَتْ النَّارُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('987f20e5-bfff-5c18-a047-93bd6cd2c849', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '177', '‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏وَهَارُونُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَرَمِيٌّ وَهُوَ ابْنُ عُمَارَةَ بْنِ أَبِي حَفْصَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَحْيَى بْنَ جَعْدَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو الْقَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا غَيَّرَتْ النَّارُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('af06c32e-7c44-5840-84b0-82824a071367', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '178', '‏ ‏أَخْبَرَنَا ‏ ‏هَارُونُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرَمِيُّ بْنُ عُمَارَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَفْصٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا أَنْضَجَتْ النَّارُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
