insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('653ff850-2c5e-59a9-9bea-68def0bcf7fb', 'f22bbf4a-bcb7-4cfc-b85b-e632e5433f79', '180', '‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّبَيْدِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي سُفْيَانَ بْنِ سَعِيدِ بْنِ الْأَخْنَسِ بْنِ شَرِيقٍ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏أُمِّ حَبِيبَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ خَالَتُهُ فَسَقَتْهُ ‏ ‏سَوِيقًا ‏ ‏ثُمَّ قَالَتْ لَهُ تَوَضَّأْ يَا ابْنَ أُخْتِي فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏', 'سنن النسائي — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
