insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('57b0e79b-67c4-528c-bf06-7bdca0faaf10', '889435ea-32e0-4b03-ab10-97e68c0eef82', '1', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَمَرْتُكُمْ بِهِ فَخُذُوهُ وَمَا نَهَيْتُكُمْ عَنْهُ فَانْتَهُوا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3d84dcc5-1ee3-5470-bd16-3dd70b0fb40a', '889435ea-32e0-4b03-ab10-97e68c0eef82', '2', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَرُونِي مَا تَرَكْتُكُمْ فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِسُؤَالِهِمْ وَاخْتِلَافِهِمْ عَلَى أَنْبِيَائِهِمْ فَإِذَا أَمَرْتُكُمْ بِشَيْءٍ فَخُذُوا مِنْهُ مَا اسْتَطَعْتُمْ وَإِذَا نَهَيْتُكُمْ عَنْ شَيْءٍ فَانْتَهُوا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4a6b2fb6-da33-5384-9cf3-6403298363b4', '889435ea-32e0-4b03-ab10-97e68c0eef82', '3', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cd6fb6ce-8c8c-5f92-8fbb-c94f73cd902b', '889435ea-32e0-4b03-ab10-97e68c0eef82', '4', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سُوقَةَ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِذَا سَمِعَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثًا لَمْ يَعْدُهُ وَلَمْ يُقَصِّرْ دُونَهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2982e4d7-8cbc-543d-bbbb-00aa370526de', '889435ea-32e0-4b03-ab10-97e68c0eef82', '5', '‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَمَّارٍ الدِّمَشْقِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى بْنِ سُمَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سُلَيْمَانَ الْأَفْطَسُ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ عَبْدِ الرَّحْمَنِ الْجُرَشِيِّ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ نَذْكُرُ الْفَقْرَ وَنَتَخَوَّفُهُ فَقَالَ ‏ ‏أَالْفَقْرَ تَخَافُونَ وَالَّذِي نَفْسِي بِيَدِهِ لَتُصَبَّنَّ عَلَيْكُمْ الدُّنْيَا صَبًّا حَتَّى لَا ‏ ‏يُزِيغَ ‏ ‏قَلْبَ أَحَدِكُمْ إِزَاغَةً إِلَّا ‏ ‏هِيهْ وَايْمُ اللَّهِ لَقَدْ تَرَكْتُكُمْ عَلَى مِثْلِ الْبَيْضَاءِ لَيْلُهَا وَنَهَارُهَا سَوَاءٌ ‏ ‏قَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏صَدَقَ وَاللَّهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَرَكَنَا وَاللَّهِ عَلَى مِثْلِ الْبَيْضَاءِ لَيْلُهَا وَنَهَارُهَا سَوَاءٌ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2d3025be-a439-5f55-81bd-945b79867893', '889435ea-32e0-4b03-ab10-97e68c0eef82', '6', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي مَنْصُورِينَ لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ حَتَّى تَقُومَ السَّاعَةُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('acf7d6e4-1756-5de1-b6e4-dea67d460959', '889435ea-32e0-4b03-ab10-97e68c0eef82', '7', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَمَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَلْقَمَةَ نَصْرُ بْنُ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عُمَيْرِ بْنِ الْأَسْوَدِ ‏ ‏وَكَثِيرِ بْنِ مُرَّةَ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي قَوَّامَةً عَلَى أَمْرِ اللَّهِ لَا يَضُرُّهَا مَنْ خَالَفَهَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('069cd6d9-8dac-58ed-9474-ec306971a8f5', '889435ea-32e0-4b03-ab10-97e68c0eef82', '8', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏الْجَرَّاحُ بْنُ مَلِيحٍ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ زُرْعَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عِنَبَةَ الْخَوْلَانِيَّ ‏ ‏وَكَانَ قَدْ صَلَّى الْقِبْلَتَيْنِ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَزَالُ اللَّهُ يَغْرِسُ فِي هَذَا الدِّينِ غَرْسًا يَسْتَعْمِلُهُمْ فِي طَاعَتِهِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('862122e2-0d08-57d5-95df-806a291dafbd', '889435ea-32e0-4b03-ab10-97e68c0eef82', '9', '‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ حُمَيْدِ بْنِ كَاسِبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَامَ ‏ ‏مُعَاوِيَةُ ‏ ‏خَطِيبًا فَقَالَ أَيْنَ عُلَمَاؤُكُمْ أَيْنَ عُلَمَاؤُكُمْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَقُومُ السَّاعَةُ إِلَّا وَطَائِفَةٌ مِنْ أُمَّتِي ظَاهِرُونَ عَلَى النَّاسِ لَا يُبَالُونَ مَنْ خَذَلَهُمْ وَلَا مَنْ نَصَرَهُمْ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d97165be-7479-5034-938e-9c8bbef1b9e5', '889435ea-32e0-4b03-ab10-97e68c0eef82', '10', '‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ شُعَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ بَشِيرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ مَنْصُورِينَ لَا يَضُرُّهُمْ مَنْ خَالَفَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ عَزَّ وَجَلَّ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8bd75c8f-7cc2-57eb-8110-d7c2fe8c5b7f', '889435ea-32e0-4b03-ab10-97e68c0eef82', '11', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُجَالِدًا ‏ ‏يَذْكُرُ عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَطَّ خَطًّا وَخَطَّ خَطَّيْنِ عَنْ يَمِينِهِ وَخَطَّ خَطَّيْنِ عَنْ يَسَارِهِ ثُمَّ وَضَعَ يَدَهُ فِي الْخَطِّ الْأَوْسَطِ فَقَالَ ‏ ‏هَذَا سَبِيلُ اللَّهِ ثُمَّ تَلَا هَذِهِ الْآيَةَ ‏ { ‏وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ ‏}', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9a2790b6-d69f-5ce3-88b6-831115d7588a', '889435ea-32e0-4b03-ab10-97e68c0eef82', '12', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏الْحَسَنُ بْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ الْكِنْدِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُوشِكُ الرَّجُلُ مُتَّكِئًا عَلَى ‏ ‏أَرِيكَتِهِ ‏ ‏يُحَدَّثُ بِحَدِيثٍ مِنْ حَدِيثِي فَيَقُولُ بَيْنَنَا وَبَيْنَكُمْ كِتَابُ اللَّهِ عَزَّ وَجَلَّ مَا وَجَدْنَا فِيهِ مِنْ حَلَالٍ اسْتَحْلَلْنَاهُ وَمَا وَجَدْنَا فِيهِ مِنْ حَرَامٍ حَرَّمْنَاهُ أَلَّا وَإِنَّ مَا حَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلُ مَا حَرَّمَ اللَّهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d701696a-3742-581a-8f24-8243c14df8f5', '889435ea-32e0-4b03-ab10-97e68c0eef82', '13', '‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏فِي بَيْتِهِ أَنَا سَأَلْتُهُ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏ثُمَّ مَرَّ فِي الْحَدِيثِ ‏ ‏قَالَ ‏ ‏أَوْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا أُلْفِيَنَّ أَحَدَكُمْ مُتَّكِئًا عَلَى ‏ ‏أَرِيكَتِهِ ‏ ‏يَأْتِيهِ الْأَمْرُ مِمَّا أَمَرْتُ بِهِ أَوْ نَهَيْتُ عَنْهُ فَيَقُولُ لَا أَدْرِي مَا وَجَدْنَا فِي كِتَابِ اللَّهِ اتَّبَعْنَاهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('32e74be2-0b36-5e28-bdea-880ec6538b51', '889435ea-32e0-4b03-ab10-97e68c0eef82', '14', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَرْوَانَ مُحَمَّدُ بْنُ عُثْمَانَ الْعُثْمَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدِ بْنِ إِبْرَاهِيمَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏أَحْدَثَ ‏ ‏فِي أَمْرِنَا هَذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('321fdc68-e1d4-5479-8a59-f3d1625502c0', '889435ea-32e0-4b03-ab10-97e68c0eef82', '15', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رُمْحِ بْنِ الْمُهَاجِرِ الْمِصْرِيُّ ‏ ‏أَنْبَأَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏خَاصَمَ ‏ ‏الزُّبَيْرَ ‏ ‏عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏شِرَاجِ الْحَرَّةِ ‏ ‏الَّتِي يَسْقُونَ بِهَا النَّخْلَ فَقَالَ الْأَنْصَارِيُّ ‏ ‏سَرِّحْ ‏ ‏الْمَاءَ يَمُرُّ فَأَبَى عَلَيْهِ فَاخْتَصَمَا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْقِ يَا ‏ ‏زُبَيْرُ ‏ ‏ثُمَّ أَرْسِلْ الْمَاءَ إِلَى جَارِكَ فَغَضِبَ الْأَنْصَارِيُّ فَقَالَ يَا رَسُولَ اللَّهِ أَنْ كَانَ ابْنَ عَمَّتِكَ فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ يَا ‏ ‏زُبَيْرُ ‏ ‏اسْقِ ثُمَّ احْبِسْ الْمَاءَ حَتَّى يَرْجِعَ إِلَى ‏ ‏الْجَدْرِ ‏ ‏قَالَ فَقَالَ ‏ ‏الزُّبَيْرُ ‏ ‏وَاللَّهِ إِنِّي لَأَحْسِبُ هَذِهِ الْآيَةَ نَزَلَتْ فِي ذَلِكَ ‏ { ‏فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا فِي أَنْفُسِهِمْ حَرَجًا مِمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا ‏}', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e8387282-d557-51c9-8f18-1d1261dc394f', '889435ea-32e0-4b03-ab10-97e68c0eef82', '16', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَحْيَى النَّيْسَابُورِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَمْنَعُوا ‏ ‏إِمَاءَ اللَّهِ ‏ ‏أَنْ يُصَلِّينَ فِي الْمَسْجِدِ ‏ ‏فَقَالَ ابْنٌ لَهُ إِنَّا لَنَمْنَعُهُنَّ فَغَضِبَ غَضَبًا شَدِيدًا وَقَالَ ‏ ‏أُحَدِّثُكَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقُولُ إِنَّا لَنَمْنَعُهُنَّ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ad9727bf-a5df-50d1-939d-06b431587a5d', '889435ea-32e0-4b03-ab10-97e68c0eef82', '17', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ ثَابِتٍ الْجَحْدَرِيُّ ‏ ‏وَأَبُو عَمْرٍو حَفْصُ بْنُ عُمَرَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏أَنَّهُ كَانَ جَالِسًا إِلَى جَنْبِهِ ابْنُ أَخٍ لَهُ ‏ ‏فَخَذَفَ ‏ ‏فَنَهَاهُ وَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهَا فَقَالَ إِنَّهَا لَا تَصِيدُ صَيْدًا وَلَا ‏ ‏تَنْكِي ‏ ‏عَدُوًّا وَإِنَّهَا تَكْسِرُ السِّنَّ وَتَفْقَأُ الْعَيْنَ ‏ ‏قَالَ ‏ ‏فَعَادَ ابْنُ أَخِيهِ ‏ ‏فَخَذَفَ ‏ ‏فَقَالَ ‏ ‏أُحَدِّثُكَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهَا ثُمَّ عُدْتَ ‏ ‏تَخْذِفُ ‏ ‏لَا أُكَلِّمُكَ أَبَدًا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('87612236-2d02-5d3b-b6ac-2f78c344d1f2', '889435ea-32e0-4b03-ab10-97e68c0eef82', '18', '‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏حَدَّثَنِي ‏ ‏بُرْدُ بْنُ سِنَانٍ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ قَبِيصَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عُبَادَةَ بْنَ الصَّامِتِ الْأَنْصَارِيَّ ‏ ‏النَّقِيبَ صَاحِبَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزَا مَعَ ‏ ‏مُعَاوِيَةَ ‏ ‏أَرْضَ ‏ ‏الرُّومِ ‏ ‏فَنَظَرَ إِلَى النَّاسِ وَهُمْ يَتَبَايَعُونَ كِسَرَ الذَّهَبِ بِالدَّنَانِيرِ وَكِسَرَ الْفِضَّةِ بِالدَّرَاهِمِ فَقَالَ يَا أَيُّهَا النَّاسُ إِنَّكُمْ تَأْكُلُونَ الرِّبَا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَبْتَاعُوا الذَّهَبَ بِالذَّهَبِ إِلَّا مِثْلًا بِمِثْلٍ لَا زِيَادَةَ بَيْنَهُمَا وَلَا ‏ ‏نَظِرَةً ‏ ‏فَقَالَ لَهُ ‏ ‏مُعَاوِيَةُ ‏ ‏يَا ‏ ‏أَبَا الْوَلِيدِ ‏ ‏لَا ‏ ‏أَرَى الرِّبَا فِي هَذَا إِلَّا مَا كَانَ مِنْ ‏ ‏نَظِرَةٍ ‏ ‏فَقَالَ ‏ ‏عُبَادَةُ ‏ ‏أُحَدِّثُكَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتُحَدِّثُنِي عَنْ رَأْيِكَ لَئِنْ أَخْرَجَنِي اللَّهُ لَا أُسَاكِنُكَ بِأَرْضٍ لَكَ عَلَيَّ فِيهَا إِمْرَةٌ فَلَمَّا ‏ ‏قَفَلَ ‏ ‏لَحِقَ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَقَالَ لَهُ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏مَا أَقْدَمَكَ يَا ‏ ‏أَبَا الْوَلِيدِ ‏ ‏فَقَصَّ عَلَيْهِ الْقِصَّةَ وَمَا قَالَ مِنْ مُسَاكَنَتِهِ فَقَالَ ارْجِعْ يَا ‏ ‏أَبَا الْوَلِيدِ ‏ ‏إِلَى أَرْضِكَ فَقَبَحَ اللَّهُ أَرْضًا لَسْتَ فِيهَا وَأَمْثَالُكَ وَكَتَبَ إِلَى ‏ ‏مُعَاوِيَةَ ‏ ‏لَا إِمْرَةَ لَكَ عَلَيْهِ وَاحْمِلْ النَّاسَ عَلَى مَا قَالَ فَإِنَّهُ هُوَ الْأَمْرُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('80ddc8f9-5b36-53c6-8b05-4a1ec31e8c65', '889435ea-32e0-4b03-ab10-97e68c0eef82', '19', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ الْخَلَّادِ الْبَاهِلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏أَنْبَأَنَا ‏ ‏عَوْنُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏إِذَا حَدَّثْتُكُمْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَظُنُّوا بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي هُوَ ‏ ‏أَهْنَاهُ وَأَهْدَاهُ وَأَتْقَاهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ff94c5f4-ae4c-51c2-a378-b1ea412990d4', '889435ea-32e0-4b03-ab10-97e68c0eef82', '20', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏قَالَ ‏ ‏إِذَا حَدَّثْتُكُمْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثًا فَظُنُّوا بِهِ الَّذِي هُوَ ‏ ‏أَهْنَاهُ وَأَهْدَاهُ وَأَتْقَاهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c0cf3361-d6bc-5681-b87f-8e0682e82eba', '889435ea-32e0-4b03-ab10-97e68c0eef82', '21', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْمُنْذِرِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْفُضَيْلِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَقْبُرِيُّ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا أَعْرِفَنَّ مَا يُحَدَّثُ أَحَدُكُمْ عَنِّي الْحَدِيثَ وَهُوَ مُتَّكِئٌ عَلَى أَرِيكَتِهِ فَيَقُولُ اقْرَأْ قُرْآنًا مَا قِيلَ مِنْ قَوْلٍ حَسَنٍ فَأَنَا قُلْتُهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('db778cfd-4ccf-5e10-9821-629d2610e203', '889435ea-32e0-4b03-ab10-97e68c0eef82', '22', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبَّادِ بْنِ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏هَنَّادُ بْنُ السَّرِيِّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ لِرَجُلٍ يَا ابْنَ أَخِي ‏ ‏إِذَا حَدَّثْتُكَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثًا فَلَا تَضْرِبْ لَهُ الْأَمْثَالَ ‏ ‏قَالَ ‏ ‏أَبُو الْحَسَنِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عَبْدِ اللَّهِ الْكَرَابِيسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْجَعْدِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('13c37703-39b1-593d-805b-32b0496c4cc6', '889435ea-32e0-4b03-ab10-97e68c0eef82', '23', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمٌ الْبَطِينُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏قَالَ ‏ ‏مَا أَخْطَأَنِي ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏عَشِيَّةَ خَمِيسٍ إِلَّا أَتَيْتُهُ فِيهِ قَالَ فَمَا سَمِعْتُهُ يَقُولُ بِشَيْءٍ قَطُّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا كَانَ ذَاتَ عَشِيَّةٍ قَالَ قَالَ رَسُولُ اللَّهِ قَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَكَسَ ‏ ‏قَالَ فَنَظَرْتُ إِلَيْهِ فَهُوَ قَائِمٌ مُحَلَّلَةً أَزْرَارُ قَمِيصِهِ قَدْ اغْرَوْرَقَتْ عَيْنَاهُ وَانْتَفَخَتْ ‏ ‏أَوْدَاجُهُ ‏ ‏قَالَ ‏ ‏أَوْ دُونَ ذَلِكَ أَوْ فَوْقَ ذَلِكَ أَوْ قَرِيبًا مِنْ ذَلِكَ أَوْ شَبِيهًا بِذَلِكَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('da133061-efb8-51c7-b9a8-80aeaef96568', '889435ea-32e0-4b03-ab10-97e68c0eef82', '24', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏إِذَا حَدَّثَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثًا فَفَرَغَ مِنْهُ قَالَ أَوْ كَمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('93c9a868-5253-5bab-b0b1-5049ededc158', '889435ea-32e0-4b03-ab10-97e68c0eef82', '25', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏قُلْنَا ‏ ‏لِزَيْدِ بْنِ أَرْقَمَ ‏ ‏حَدِّثْنَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَبِرْنَا وَنَسِينَا وَالْحَدِيثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَدِيدٌ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4908dc02-c6ce-5fe4-8e96-bb346b33b907', '889435ea-32e0-4b03-ab10-97e68c0eef82', '26', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي السَّفَرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏يَقُولُ ‏ ‏جَالَسْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏سَنَةً فَمَا سَمِعْتُهُ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('81f1bdeb-a56c-5323-a9d0-92d966d0c1c4', '889435ea-32e0-4b03-ab10-97e68c0eef82', '27', '‏ ‏حَدَّثَنَا ‏ ‏الْعَبَّاسُ بْنُ عَبْدِ الْعَظِيمِ الْعَنْبَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏إِنَّمَا كُنَّا نَحْفَظُ الْحَدِيثَ وَالْحَدِيثُ يُحْفَظُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَّا إِذَا رَكِبْتُمْ الصَّعْبَ ‏ ‏وَالذَّلُولَ ‏ ‏فَهَيْهَاتَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('31b4cbc5-d704-5651-a235-101ab1b991f8', '889435ea-32e0-4b03-ab10-97e68c0eef82', '28', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏قَرَظَةَ بْنِ كَعْبٍ ‏ ‏قَالَ ‏ ‏بَعَثَنَا ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏إِلَى ‏ ‏الْكُوفَةِ ‏ ‏وَشَيَّعَنَا فَمَشَى مَعَنَا إِلَى مَوْضِعٍ يُقَالُ لَهُ ‏ ‏صِرَارٌ ‏ ‏فَقَالَ أَتَدْرُونَ لِمَ مَشَيْتُ مَعَكُمْ قَالَ قُلْنَا لِحَقِّ صُحْبَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلِحَقِّ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ لَكِنِّي مَشَيْتُ مَعَكُمْ لِحَدِيثٍ أَرَدْتُ أَنْ أُحَدِّثَكُمْ بِهِ وَأَرَدْتُ أَنْ تَحْفَظُوهُ لِمَمْشَايَ مَعَكُمْ ‏ ‏إِنَّكُمْ تَقْدَمُونَ عَلَى قَوْمٍ لِلْقُرْآنِ فِي صُدُورِهِمْ ‏ ‏هَزِيزٌ ‏ ‏كَهَزِيزِ ‏ ‏الْمِرْجَلِ ‏ ‏فَإِذَا رَأَوْكُمْ مَدُّوا إِلَيْكُمْ أَعْنَاقَهُمْ وَقَالُوا ‏ ‏أَصْحَابُ ‏ ‏مُحَمَّدٍ ‏ ‏فَأَقِلُّوا الرِّوَايَةَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا شَرِيكُكُمْ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9855639f-c871-5f38-bd2a-48a4fd3476d8', '889435ea-32e0-4b03-ab10-97e68c0eef82', '29', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏صَحِبْتُ ‏ ‏سَعْدَ بْنَ مَالِكٍ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏فَمَا سَمِعْتُهُ يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحَدِيثٍ وَاحِدٍ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1ade27da-b3da-5a56-98be-953bd715eaf0', '889435ea-32e0-4b03-ab10-97e68c0eef82', '30', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَسُوَيْدُ بْنُ سَعِيدٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ عَامِرِ بْنِ زُرَارَةَ ‏ ‏وَإِسْمَعِيلُ بْنُ مُوسَى ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('11fbd20d-0e18-5e2d-b42c-58c67b82f7d1', '889435ea-32e0-4b03-ab10-97e68c0eef82', '31', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَامِرِ بْنِ زُرَارَةَ ‏ ‏وَإِسْمَعِيلُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَكْذِبُوا عَلَيَّ فَإِنَّ الْكَذِبَ عَلَيَّ يُولِجُ النَّارَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1528f0f3-80da-5662-aa9b-3f4f7e9b56c7', '889435ea-32e0-4b03-ab10-97e68c0eef82', '32', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رُمْحٍ الْمِصْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ ‏ ‏حَسِبْتُهُ قَالَ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bb082d22-d496-5632-83b0-9ccc97f57c5f', '889435ea-32e0-4b03-ab10-97e68c0eef82', '33', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَيْثَمَةَ زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('965c9236-070a-5254-8ea9-e490cf7120a3', '889435ea-32e0-4b03-ab10-97e68c0eef82', '34', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَقَوَّلَ عَلَيَّ مَا لَمْ أَقُلْ ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d767f95b-4f87-5282-bdd7-09b3a9befdcd', '889435ea-32e0-4b03-ab10-97e68c0eef82', '35', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَعْلَى التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى هَذَا الْمِنْبَرِ ‏ ‏إِيَّاكُمْ وَكَثْرَةَ الْحَدِيثِ عَنِّي فَمَنْ قَالَ عَلَيَّ فَلْيَقُلْ حَقًّا ‏ ‏أَوْ صِدْقًا ‏ ‏وَمَنْ تَقَوَّلَ عَلَيَّ مَا لَمْ أَقُلْ ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('530193c8-cdf8-5267-a312-e8c840afd08f', '889435ea-32e0-4b03-ab10-97e68c0eef82', '36', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏غُنْدَرٌ مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ أَبِي صَخْرَةَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قُلْتُ ‏ ‏لِلزُّبَيْرِ بْنِ الْعَوَّامِ ‏ ‏مَا ‏ ‏لِيَ لَا أَسْمَعُكَ تُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا أَسْمَعُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏وَفُلَانًا وَفُلَانًا قَالَ أَمَا إِنِّي لَمْ أُفَارِقْهُ مُنْذُ أَسْلَمْتُ وَلَكِنِّي سَمِعْتُ مِنْهُ كَلِمَةً يَقُولُ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cf34d1ba-8725-50ee-9878-19bba88e10c5', '889435ea-32e0-4b03-ab10-97e68c0eef82', '37', '‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6abeed95-1da2-5fc7-a502-dea8cd5c6d71', '889435ea-32e0-4b03-ab10-97e68c0eef82', '38', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ هَاشِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَدَّثَ عَنِّي حَدِيثًا وَهُوَ ‏ ‏يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبَيْنِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d886a3e9-2297-5545-b9ac-0147a2e93ec8', '889435ea-32e0-4b03-ab10-97e68c0eef82', '39', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدَبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَدَّثَ عَنِّي حَدِيثًا وَهُوَ ‏ ‏يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبَيْنِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8047836b-2377-5a61-9c19-296ca4942e64', '889435ea-32e0-4b03-ab10-97e68c0eef82', '40', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ رَوَى عَنِّي حَدِيثًا وَهُوَ ‏ ‏يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنْبَأَنَا ‏ ‏الْحَسَنُ بْنُ مُوسَى الْأَشْيَبُ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏سَمُرَةَ بْنِ جُنْدَبٍ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('92cd0720-8182-5374-ad4c-9c02e55c35b0', '889435ea-32e0-4b03-ab10-97e68c0eef82', '41', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ أَبِي شَبِيبٍ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَدَّثَ عَنِّي بِحَدِيثٍ وَهُوَ ‏ ‏يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبَيْنِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9f2add3c-ca3b-5cf1-bd79-034965ea0203', '889435ea-32e0-4b03-ab10-97e68c0eef82', '42', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَحْمَدَ بْنِ بَشِيرِ بْنِ ذَكْوَانَ الدِّمَشْقِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي الْمُطَاعِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعِرْبَاضَ بْنَ سَارِيَةَ ‏ ‏يَقُولُ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ فَوَعَظَنَا مَوْعِظَةً بَلِيغَةً وَجِلَتْ مِنْهَا الْقُلُوبُ وَذَرَفَتْ مِنْهَا الْعُيُونُ فَقِيلَ يَا رَسُولَ اللَّهِ وَعَظْتَنَا مَوْعِظَةَ مُوَدِّعٍ فَاعْهَدْ إِلَيْنَا بِعَهْدٍ فَقَالَ ‏ ‏عَلَيْكُمْ بِتَقْوَى اللَّهِ وَالسَّمْعِ وَالطَّاعَةِ وَإِنْ عَبْدًا حَبَشِيًّا وَسَتَرَوْنَ مِنْ بَعْدِي اخْتِلَافًا شَدِيدًا فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ عَضُّوا عَلَيْهَا ‏ ‏بِالنَّوَاجِذِ ‏ ‏وَإِيَّاكُمْ وَالْأُمُورَ الْمُحْدَثَاتِ فَإِنَّ كُلَّ بِدْعَةٍ ضَلَالَةٌ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('41b5d0c8-2f3d-5953-9918-725ac6e4d097', '889435ea-32e0-4b03-ab10-97e68c0eef82', '43', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ بِشْرِ بْنِ مَنْصُورٍ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ السَّوَّاقُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ بْنِ حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَمْرٍو السُّلَمِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏الْعِرْبَاضَ بْنَ سَارِيَةَ ‏ ‏يَقُولُ ‏ ‏وَعَظَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَوْعِظَةً ‏ ‏ذَرَفَتْ ‏ ‏مِنْهَا الْعُيُونُ ‏ ‏وَوَجِلَتْ ‏ ‏مِنْهَا الْقُلُوبُ فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّ هَذِهِ لَمَوْعِظَةُ مُوَدِّعٍ فَمَاذَا تَعْهَدُ إِلَيْنَا قَالَ ‏ ‏قَدْ تَرَكْتُكُمْ عَلَى الْبَيْضَاءِ لَيْلُهَا كَنَهَارِهَا لَا ‏ ‏يَزِيغُ ‏ ‏عَنْهَا بَعْدِي إِلَّا هَالِكٌ مَنْ يَعِشْ مِنْكُمْ فَسَيَرَى اخْتِلَافًا كَثِيرًا فَعَلَيْكُمْ بِمَا عَرَفْتُمْ مِنْ سُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ عَضُّوا عَلَيْهَا ‏ ‏بِالنَّوَاجِذِ ‏ ‏وَعَلَيْكُمْ بِالطَّاعَةِ وَإِنْ عَبْدًا حَبَشِيًّا فَإِنَّمَا الْمُؤْمِنُ كَالْجَمَلِ ‏ ‏الْأَنِفِ ‏ ‏حَيْثُمَا قِيدَ انْقَادَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَكِيمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ الصَّبَّاحِ الْمِسْمَعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ثَوْرُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏الْعِرْبَاضِ بْنِ سَارِيَةَ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الصُّبْحِ ثُمَّ أَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَوَعَظَنَا مَوْعِظَةً بَلِيغَةً فَذَكَرَ نَحْوَهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3a9e8eaa-af36-5104-bcb7-2dc7880bc2ba', '889435ea-32e0-4b03-ab10-97e68c0eef82', '44', '‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏وَأَحْمَدُ بْنُ ثَابِتٍ الْجَحْدَرِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَطَبَ احْمَرَّتْ عَيْنَاهُ وَعَلَا صَوْتُهُ وَاشْتَدَّ غَضَبُهُ كَأَنَّهُ مُنْذِرُ جَيْشٍ يَقُولُ صَبَّحَكُمْ مَسَّاكُمْ وَيَقُولُ بُعِثْتُ أَنَا وَالسَّاعَةَ كَهَاتَيْنِ وَيَقْرِنُ بَيْنَ إِصْبَعَيْهِ السَّبَّابَةِ وَالْوُسْطَى وَيَقُولُ أَمَّا بَعْدُ ‏ ‏فَإِنَّ خَيْرَ الْأُمُورِ كِتَابُ اللَّهِ وَخَيْرُ الْهَدْيِ هَدْيُ ‏ ‏مُحَمَّدٍ ‏ ‏وَشَرُّ الْأُمُورِ ‏ ‏مُحْدَثَاتُهَا ‏ ‏وَكُلُّ بِدْعَةٍ ضَلَالَةٌ وَكَانَ يَقُولُ مَنْ تَرَكَ مَالًا فَلِأَهْلِهِ وَمَنْ تَرَكَ دَيْنًا أَوْ ‏ ‏ضَيَاعًا ‏ ‏فَعَلَيَّ وَإِلَيَّ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c50da685-4f8b-589e-8ad8-4d82e5e9e92f', '889435ea-32e0-4b03-ab10-97e68c0eef82', '45', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدِ بْنِ مَيْمُونٍ الْمَدَنِيُّ أَبُو عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا هُمَا اثْنَتَانِ الْكَلَامُ وَالْهَدْيُ فَأَحْسَنُ الْكَلَامِ كَلَامُ اللَّهِ وَأَحْسَنُ الْهَدْيِ هَدْيُ ‏ ‏مُحَمَّدٍ ‏ ‏أَلَا وَإِيَّاكُمْ ‏ ‏وَمُحْدِثَاتِ ‏ ‏الْأُمُورِ فَإِنَّ شَرَّ الْأُمُورِ ‏ ‏مُحْدَثَاتُهَا ‏ ‏وَكُلُّ مُحْدَثَةٍ بِدْعَةٌ وَكُلُّ بِدْعَةٍ ضَلَالَةٌ أَلَا لَا يَطُولَنَّ عَلَيْكُمْ الْأَمَدُ فَتَقْسُوَ قُلُوبُكُمْ أَلَا إِنَّ مَا هُوَ آتٍ قَرِيبٌ وَإِنَّمَا الْبَعِيدُ مَا لَيْسَ بِآتٍ أَلَا أَنَّمَا الشَّقِيُّ مَنْ شَقِيَ فِي بَطْنِ أُمِّهِ وَالسَّعِيدُ مَنْ وُعِظَ بِغَيْرِهِ أَلَا إِنَّ قِتَالَ الْمُؤْمِنِ كُفْرٌ وَسِبَابُهُ فُسُوقٌ وَلَا يَحِلُّ لِمُسْلِمٍ أَنْ ‏ ‏يَهْجُرَ ‏ ‏أَخَاهُ فَوْقَ ثَلَاثٍ أَلَا وَإِيَّاكُمْ وَالْكَذِبَ فَإِنَّ الْكَذِبَ لَا يَصْلُحُ بِالْجِدِّ وَلَا بِالْهَزْلِ وَلَا يَعِدُ الرَّجُلُ صَبِيَّهُ ثُمَّ لَا يَفِي لَهُ فَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارَ وَإِنَّ الصِّدْقَ يَهْدِي إِلَى ‏ ‏الْبِرِّ ‏ ‏وَإِنَّ ‏ ‏الْبِرَّ ‏ ‏يَهْدِي إِلَى الْجَنَّةِ وَإِنَّهُ يُقَالُ لِلصَّادِقِ صَدَقَ ‏ ‏وَبَرَّ ‏ ‏وَيُقَالُ لِلْكَاذِبِ كَذَبَ وَفَجَرَ أَلَا وَإِنَّ الْعَبْدَ يَكْذِبُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّابًا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('16bc60e4-2002-5f81-ab87-1608c66c5fba', '889435ea-32e0-4b03-ab10-97e68c0eef82', '46', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ خَالِدِ بْنِ خِدَاشٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ ثَابِتٍ الْجَحْدَرِيُّ ‏ ‏وَيَحْيَى بْنُ حَكِيمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏تَلَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذِهِ الْآيَةَ ‏ { ‏هُوَ الَّذِي أَنْزَلَ عَلَيْكَ الْكِتَابَ مِنْهُ آيَاتٌ ‏ ‏مُحْكَمَاتٌ ‏ ‏هُنَّ ‏ ‏أُمُّ الْكِتَابِ ‏ ‏وَأُخَرُ ‏ ‏مُتَشَابِهَاتٌ ‏ ‏إِلَى قَوْلِهِ ‏ ‏وَمَا يَذَّكَّرُ إِلَّا أُولُوا الْأَلْبَابِ ‏} ‏فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏إِذَا رَأَيْتُمْ الَّذِينَ يُجَادِلُونَ فِيهِ فَهُمْ الَّذِينَ عَنَاهُمْ اللَّهُ فَاحْذَرُوهُمْ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('58239fb2-3e2b-5666-989a-5afab3b433c2', '889435ea-32e0-4b03-ab10-97e68c0eef82', '47', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْمُنْذِرِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏حَوْثَرَةُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي غَالِبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ضَلَّ قَوْمٌ بَعْدَ هُدًى كَانُوا عَلَيْهِ إِلَّا أُوتُوا الْجَدَلَ ثُمَّ تَلَا هَذِهِ الْآيَةَ ‏ { ‏بَلْ هُمْ قَوْمٌ خَصِمُونَ ‏} ‏الْآيَةَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dc872d93-7ce6-58c3-a39c-082586c752db', '889435ea-32e0-4b03-ab10-97e68c0eef82', '48', '‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ سُلَيْمَانَ الْعَسْكَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَلِيٍّ أَبُو هَاشِمِ بْنِ أَبِي خِدَاشٍ الْمَوْصِلِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مِحْصَنٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ أَبِي عَبْلَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الدَّيْلَمِيِّ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقْبَلُ اللَّهُ لِصَاحِبِ بِدْعَةٍ صَوْمًا وَلَا صَلَاةً وَلَا صَدَقَةً وَلَا حَجًّا وَلَا عُمْرَةً وَلَا جِهَادًا وَلَا ‏ ‏صَرْفًا ‏ ‏وَلَا ‏ ‏عَدْلًا ‏ ‏يَخْرُجُ مِنْ الْإِسْلَامِ كَمَا تَخْرُجُ الشَّعَرَةُ مِنْ الْعَجِينِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8208f459-8bc8-5022-8de0-17f7926cec8c', '889435ea-32e0-4b03-ab10-97e68c0eef82', '49', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ مَنْصُورٍ الْحَنَّاطُ ‏ ‏عَنْ ‏ ‏أَبِي زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَى اللَّهُ أَنْ يَقْبَلَ عَمَلَ صَاحِبِ بِدْعَةٍ حَتَّى يَدَعَ بِدْعَتَهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d8aa9a84-b7c9-52fc-82da-273fc3b794bf', '889435ea-32e0-4b03-ab10-97e68c0eef82', '50', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ الدِّمَشْقِيُّ ‏ ‏وَهَارُونُ بْنُ إِسْحَقَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ أَبِي فُدَيْكٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ وَرْدَانَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَرَكَ الْكَذِبَ وَهُوَ بَاطِلٌ بُنِيَ لَهُ قَصْرٌ فِي ‏ ‏رَبَضِ الْجَنَّةِ ‏ ‏وَمَنْ تَرَكَ ‏ ‏الْمِرَاءَ ‏ ‏وَهُوَ مُحِقٌّ بُنِيَ لَهُ فِي وَسَطِهَا وَمَنْ حَسَّنَ خُلُقَةُ بُنِيَ لَهُ فِي أَعْلَاهَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f94cae98-ac3e-5973-a48a-bb6975b7c365', '889435ea-32e0-4b03-ab10-97e68c0eef82', '51', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏وَعَبْدَةُ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏وَمُحَمَّدُ بْنُ بِشْرٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏وَمَالِكُ بْنُ أَنَسٍ ‏ ‏وَحَفْصُ بْنُ مَيْسَرَةَ ‏ ‏وَشُعَيْبُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ لَا يَقْبِضُ الْعِلْمَ انْتِزَاعًا يَنْتَزِعُهُ مِنْ النَّاسِ وَلَكِنْ يَقْبِضُ الْعِلْمُ بِقَبْضِ الْعُلَمَاءِ فَإِذَا لَمْ يُبْقِ عَالِمًا اتَّخَذَ النَّاسُ رُءُوسًا جُهَّالًا فَسُئِلُوا فَأَفْتَوْا بِغَيْرِ عِلْمٍ فَضَلُّوا وَأَضَلُّوا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('00af653e-fbd9-558b-a410-e31fbc35a92f', '889435ea-32e0-4b03-ab10-97e68c0eef82', '52', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو هَانِئٍ حُمَيْدُ بْنُ هَانِئٍ الْخَوْلَانِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ مُسْلِمِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أُفْتِيَ بِفُتْيَا غَيْرَ ‏ ‏ثَبَتٍ ‏ ‏فَإِنَّمَا إِثْمُهُ عَلَى مَنْ أَفْتَاهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('10bcb06f-5716-56e9-bfd5-ff8bbb98c6e8', '889435ea-32e0-4b03-ab10-97e68c0eef82', '53', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ الْهَمْدَانِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏وَجَعْفَرُ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَنْعُمٍ هُوَ الْإِفْرِيقِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ رَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِلْمُ ثَلَاثَةٌ فَمَا وَرَاءَ ذَلِكَ فَهُوَ ‏ ‏فَضْلٌ ‏ ‏آيَةٌ مُحْكَمَةٌ ‏ ‏أَوْ سُنَّةٌ قَائِمَةٌ أَوْ ‏ ‏فَرِيضَةٌ ‏ ‏عَادِلَةٌ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7c6be29d-8b75-5773-a0c2-007268886030', '889435ea-32e0-4b03-ab10-97e68c0eef82', '54', '‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ حَمَّادٍ سَجَّادَةُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعِيدِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏عُبَادَةَ بْنِ نُسَيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏قَالَ ‏ ‏لَمَّا بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏قَالَ ‏ ‏لَا تَقْضِيَنَّ وَلَا تَفْصِلَنَّ إِلَّا بِمَا تَعْلَمُ فَإِنْ أَشْكَلَ عَلَيْكَ أَمْرٌ فَقِفْ حَتَّى تَبَيَّنَهُ أَوْ تَكْتُبَ إِلَيَّ فِيهِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ccd13261-5634-5350-af50-232e31779fc4', '889435ea-32e0-4b03-ab10-97e68c0eef82', '55', '‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الرِّجَالِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَمْرٍو الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏عَبْدَةَ بْنِ أَبِي لُبَابَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَمْ يَزَلْ أَمْرُ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏مُعْتَدِلًا حَتَّى نَشَأَ فِيهِمْ الْمُوَلَّدُونَ أَبْنَاءُ ‏ ‏سَبَايَا ‏ ‏الْأُمَمِ فَقَالُوا بِالرَّأْيِ فَضَلُّوا وَأَضَلُّوا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d6946e8e-9c9e-562a-82e2-747fc24edf1d', '889435ea-32e0-4b03-ab10-97e68c0eef82', '56', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ الطَّنَافِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِيمَانُ ‏ ‏بِضْعٌ ‏ ‏وَسِتُّونَ ‏ ‏أَوْ سَبْعُونَ ‏ ‏بَابًا أَدْنَاهَا ‏ ‏إِمَاطَةُ ‏ ‏الْأَذَى عَنْ الطَّرِيقِ وَأَرْفَعُهَا قَوْلُ لَا إِلَهَ إِلَّا اللَّهُ وَالْحَيَاءُ ‏ ‏شُعْبَةٌ ‏ ‏مِنْ الْإِيمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَمْرُو بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('64a0f4ee-d4e7-5a1f-93a0-287116b46417', '889435ea-32e0-4b03-ab10-97e68c0eef82', '57', '‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ أَبِي سَهْلٍ ‏ ‏وَمُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا يَعِظُ أَخَاهُ فِي الْحَيَاءِ فَقَالَ إِنَّ ‏ ‏الْحَيَاءَ ‏ ‏شُعْبَةٌ ‏ ‏مِنْ الْإِيمَانِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2545e47d-f106-5601-aa8b-1b98efb5650f', '889435ea-32e0-4b03-ab10-97e68c0eef82', '58', '‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مَيْمُونٍ الرَّقِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ ‏ ‏خَرْدَلٍ ‏ ‏مِنْ كِبْرٍ وَلَا يَدْخُلُ النَّارَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ ‏ ‏خَرْدَلٍ ‏ ‏مِنْ إِيمَانٍ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e1d74273-f663-5d71-a0d1-7c620c9a3008', '889435ea-32e0-4b03-ab10-97e68c0eef82', '59', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَلَّصَ اللَّهُ الْمُؤْمِنِينَ مِنْ النَّارِ وَأَمِنُوا فَمَا مُجَادَلَةُ أَحَدِكُمْ لِصَاحِبِهِ فِي الْحَقِّ يَكُونُ لَهُ فِي الدُّنْيَا أَشَدَّ مُجَادَلَةً مِنْ الْمُؤْمِنِينَ لِرَبِّهِمْ فِي إِخْوَانِهِمْ الَّذِينَ أُدْخِلُوا النَّارَ قَالَ يَقُولُونَ رَبَّنَا إِخْوَانُنَا كَانُوا يُصَلُّونَ مَعَنَا وَيَصُومُونَ مَعَنَا وَيَحُجُّونَ مَعَنَا فَأَدْخَلْتَهُمْ النَّارَ فَيَقُولُ ‏ ‏اذْهَبُوا فَأَخْرِجُوا مَنْ عَرَفْتُمْ مِنْهُمْ فَيَأْتُونَهُمْ فَيَعْرِفُونَهُمْ بِصُوَرِهِمْ لَا تَأْكُلُ النَّارُ صُوَرَهُمْ فَمِنْهُمْ مَنْ أَخَذَتْهُ النَّارُ إِلَى أَنْصَافِ سَاقَيْهِ وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى ‏ ‏كَعْبَيْهِ ‏ ‏فَيُخْرِجُونَهُمْ فَيَقُولُونَ رَبَّنَا أَخْرَجْنَا مَنْ قَدْ أَمَرْتَنَا ثُمَّ يَقُولُ أَخْرِجُوا مَنْ كَانَ فِي قَلْبِهِ وَزْنُ دِينَارٍ مِنْ الْإِيمَانِ ثُمَّ مَنْ كَانَ فِي قَلْبِهِ وَزْنُ نِصْفِ دِينَارٍ ثُمَّ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ ‏ ‏خَرْدَلٍ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَمَنْ لَمْ يُصَدِّقْ هَذَا فَلْيَقْرَأْ ‏ { ‏إِنَّ اللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِنْ تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا ‏}', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2d665db4-780a-5bd0-984c-5ba12385921e', '889435ea-32e0-4b03-ab10-97e68c0eef82', '60', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ نَجِيحٍ ‏ ‏وَكَانَ ثِقَةً ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏جُنْدُبِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ فِتْيَانٌ ‏ ‏حَزَاوِرَةٌ ‏ ‏فَتَعَلَّمْنَا الْإِيمَانَ قَبْلَ أَنْ نَتَعَلَّمَ الْقُرْآنَ ثُمَّ تَعَلَّمْنَا الْقُرْآنَ فَازْدَدْنَا بِهِ إِيمَانًا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
