insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('586ca49c-0da4-56c5-a6e6-9133c6779d7a', '889435ea-32e0-4b03-ab10-97e68c0eef82', '62', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏كَهْمَسِ بْنِ الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ رَجُلٌ شَدِيدُ بَيَاضِ الثِّيَابِ شَدِيدُ سَوَادِ شَعَرِ الرَّأْسِ لَا ‏ ‏يُرَى عَلَيْهِ أَثَرُ سَفَرٍ وَلَا يَعْرِفُهُ مِنَّا أَحَدٌ فَجَلَسَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْنَدَ رُكْبَتَهُ إِلَى رُكْبَتِهِ وَوَضَعَ يَدَيْهِ عَلَى فَخِذَيْهِ ثُمَّ قَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏مَا الْإِسْلَامُ قَالَ ‏ ‏شَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ وَإِقَامُ الصَّلَاةِ وَإِيتَاءُ الزَّكَاةِ وَصَوْمُ رَمَضَانَ وَحَجُّ ‏ ‏الْبَيْتِ ‏ ‏فَقَالَ صَدَقْتَ فَعَجِبْنَا مِنْهُ يَسْأَلُهُ وَيُصَدِّقُهُ ثُمَّ قَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏مَا الْإِيمَانُ قَالَ أَنْ تُؤْمِنَ بِاللَّهِ وَمَلَائِكَتِهِ وَرُسُلِهِ وَكُتُبِهِ وَالْيَوْمِ الْآخِرِ وَالْقَدَرِ خَيْرِهِ وَشَرِّهِ قَالَ صَدَقْتَ فَعَجِبْنَا مِنْهُ يَسْأَلُهُ وَيُصَدِّقُهُ ثُمَّ قَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏مَا الْإِحْسَانُ قَالَ أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنَّكَ إِنْ لَا تَرَاهُ فَإِنَّهُ يَرَاكَ قَالَ فَمَتَى السَّاعَةُ قَالَ مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنْ السَّائِلِ قَالَ فَمَا ‏ ‏أَمَارَتُهَا ‏ ‏قَالَ أَنْ تَلِدَ الْأَمَةُ ‏ ‏رَبَّتَهَا ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏يَعْنِي تَلِدُ ‏ ‏الْعَجَمُ ‏ ‏الْعَرَبَ ‏ ‏وَأَنْ ‏ ‏تَرَى الْحُفَاةَ الْعُرَاةَ ‏ ‏الْعَالَةَ ‏ ‏رِعَاءَ الشَّاءِ يَتَطَاوَلُونَ فِي الْبِنَاءِ قَالَ ثُمَّ قَالَ فَلَقِيَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ ثَلَاثٍ فَقَالَ أَتَدْرِي مَنْ الرَّجُلُ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ذَاكَ ‏ ‏جِبْرِيلُ ‏ ‏أَتَاكُمْ يُعَلِّمُكُمْ مَعَالِمَ دِينِكُمْ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ab39dd09-ff98-566f-ab75-c7b94f010308', '889435ea-32e0-4b03-ab10-97e68c0eef82', '63', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي حَيَّانَ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا بَارِزًا لِلنَّاسِ فَأَتَاهُ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ مَا الْإِيمَانُ قَالَ ‏ ‏أَنْ تُؤْمِنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَلِقَائِهِ وَتُؤْمِنَ بِالْبَعْثِ الْآخِرِ قَالَ يَا رَسُولَ اللَّهِ مَا الْإِسْلَامُ قَالَ أَنْ تَعْبُدَ اللَّهَ وَلَا تُشْرِكَ بِهِ شَيْئًا وَتُقِيمَ الصَّلَاةَ الْمَكْتُوبَةَ وَتُؤَدِّيَ الزَّكَاةَ الْمَفْرُوضَةَ وَتَصُومَ رَمَضَانَ قَالَ يَا رَسُولَ اللَّهِ مَا الْإِحْسَانُ قَالَ أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنَّكَ إِنْ لَا تَرَاهُ فَإِنَّهُ يَرَاكَ قَالَ يَا رَسُولَ اللَّهِ مَتَى السَّاعَةُ قَالَ مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنْ السَّائِلِ وَلَكِنْ سَأُحَدِّثُكَ عَنْ ‏ ‏أَشْرَاطِهَا ‏ ‏إِذَا وَلَدَتْ الْأَمَةُ ‏ ‏رَبَّتَهَا ‏ ‏فَذَلِكَ مِنْ ‏ ‏أَشْرَاطِهَا ‏ ‏وَإِذَا تَطَاوَلَ رِعَاءُ الْغَنَمِ فِي الْبُنْيَانِ فَذَلِكَ مِنْ ‏ ‏أَشْرَاطِهَا ‏ ‏فِي خَمْسٍ لَا يَعْلَمُهُنَّ إِلَّا اللَّهُ فَتَلَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ ‏ ‏الْغَيْثَ ‏ ‏وَيَعْلَمُ مَا فِي الْأَرْحَامِ وَمَا ‏ ‏تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا ‏ ‏تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ ‏} ‏الْآيَةَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('119e4ebd-3101-5e9e-8484-2ffb9b2e28bd', '889435ea-32e0-4b03-ab10-97e68c0eef82', '64', '‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ أَبِي سَهْلٍ ‏ ‏وَمُحَمَّدُ بْنُ إِسْمَعِيلَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ السَّلَامِ بْنُ صَالِحٍ أَبُو الصَّلْتِ الْهَرَوِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُوسَى الرِّضَا ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْحُسَيْنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِيمَانُ مَعْرِفَةٌ بِالْقَلْبِ وَقَوْلٌ بِاللِّسَانِ وَعَمَلٌ بِالْأَرْكَانِ ‏ ‏قَالَ ‏ ‏أَبُو الصَّلْتِ ‏ ‏لَوْ قُرِئَ هَذَا الْإِسْنَادُ عَلَى مَجْنُونٍ لَبَرَأَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b46fcdb2-10db-5093-be57-86ad156046d8', '889435ea-32e0-4b03-ab10-97e68c0eef82', '65', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏وَمُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ ‏ ‏أَوْ قَالَ لِجَارِهِ ‏ ‏مَا يُحِبُّ لِنَفْسِهِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a0320102-d257-58c0-92bb-98a95e79886c', '889435ea-32e0-4b03-ab10-97e68c0eef82', '66', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏وَمُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَلَدِهِ وَوَالِدِهِ وَالنَّاسِ أَجْمَعِينَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('75fa79e6-b304-52ac-a569-268da83f8284', '889435ea-32e0-4b03-ab10-97e68c0eef82', '67', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَا تَدْخُلُوا الْجَنَّةَ حَتَّى تُؤْمِنُوا وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا ‏ ‏أَوَ لَا أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ أَفْشُوا السَّلَامَ بَيْنَكُمْ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0e72871f-4702-5472-9d9f-7718f84187a9', '889435ea-32e0-4b03-ab10-97e68c0eef82', '68', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِبَابُ الْمُسْلِمِ فُسُوقٌ وَقِتَالُهُ كُفْرٌ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b14a381d-a321-5056-84c4-a79ffbd40e74', '889435ea-32e0-4b03-ab10-97e68c0eef82', '69', '‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الرَّازِيُّ ‏ ‏عَنْ ‏ ‏الرَّبِيعِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ فَارَقَ الدُّنْيَا عَلَى الْإِخْلَاصِ لِلَّهِ وَحْدَهُ وَعِبَادَتِهِ لَا شَرِيكَ لَهُ وَإِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ مَاتَ وَاللَّهُ عَنْهُ رَاضٍ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏وَهُوَ دِينُ اللَّهِ الَّذِي جَاءَتْ بِهِ الرُّسُلُ وَبَلَّغُوهُ عَنْ رَبِّهِمْ قَبْلَ هَرْجِ الْأَحَادِيثِ وَاخْتِلَافِ الْأَهْوَاءِ وَتَصْدِيقُ ذَلِكَ فِي كِتَابِ اللَّهِ فِي آخِرِ مَا نَزَلَ يَقُولُ اللَّهُ ‏ { ‏فَإِنْ تَابُوا ‏} ‏قَالَ خَلْعُ الْأَوْثَانِ وَعِبَادَتِهَا ‏ { ‏وَأَقَامُوا الصَّلَاةَ وَآتَوْا الزَّكَاةَ ‏} ‏وَقَالَ فِي آيَةٍ أُخْرَى ‏ { ‏فَإِنْ تَابُوا وَأَقَامُوا الصَّلَاةَ وَآتَوْا الزَّكَاةَ فَإِخْوَانُكُمْ فِي الدِّينِ ‏} ‏حَدَّثَنَا ‏ ‏أَبُو حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى الْعَبْسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الرَّازِيُّ ‏ ‏عَنْ ‏ ‏الرَّبِيعِ بْنِ أَنَسٍ ‏ ‏مِثْلَهُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('83845e5c-741b-5b0b-b6c4-5318b27b9be4', '889435ea-32e0-4b03-ab10-97e68c0eef82', '70', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْأَزْهَرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ وَيُقِيمُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('11c28e0d-9f51-5f19-a522-43a67b9c8589', '889435ea-32e0-4b03-ab10-97e68c0eef82', '71', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْأَزْهَرِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ بَهْرَامَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏عَنْ ‏ ‏مُعَاذِ بْنِ جَبَلٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ وَيُقِيمُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a63a2fb8-ea30-5913-8e6b-620685240ffa', '889435ea-32e0-4b03-ab10-97e68c0eef82', '72', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَعِيلَ الرَّازِيُّ ‏ ‏أَنْبَأَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ اللَّيْثِيُّ ‏ ‏حَدَّثَنَا ‏ ‏نِزَارُ بْنُ حَيَّانَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَعَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صِنْفَانِ مِنْ أُمَّتِي لَيْسَ لَهُمَا فِي الْإِسْلَامِ نَصِيبٌ أَهْلُ ‏ ‏الْإِرْجَاءِ ‏ ‏وَأَهْلُ الْقَدَرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُثْمَانَ الْبُخَارِيُّ سَعِيدُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْهَيْثَمُ بْنُ خَارِجَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَعِيلُ يَعْنِي ابْنَ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْوَهَّابِ بْنِ مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَعَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَا الْإِيمَانُ يَزِيدُ وَيَنْقُصُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُثْمَانَ الْبُخَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْهَيْثَمُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏عَنْ ‏ ‏حَرِيزِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏الْحَارِثِ ‏ ‏أَظُنُّهُ عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ الْإِيمَانُ يَزْدَادُ وَيَنْقُصُ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d35bff63-edb5-517e-9a17-75bd7f6b8568', '889435ea-32e0-4b03-ab10-97e68c0eef82', '73', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَمُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مَيْمُونٍ الرَّقِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَمُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏حَدَّثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ الصَّادِقُ الْمَصْدُوقُ أَنَّهُ ‏ ‏يُجْمَعُ خَلْقُ أَحَدِكُمْ فِي بَطْنِ أُمِّهِ أَرْبَعِينَ يَوْمًا ثُمَّ يَكُونُ عَلَقَةً مِثْلَ ذَلِكَ ثُمَّ يَكُونُ ‏ ‏مُضْغَةً ‏ ‏مِثْلَ ذَلِكَ ثُمَّ يَبْعَثُ اللَّهُ إِلَيْهِ الْمَلَكَ فَيُؤْمَرُ بِأَرْبَعِ كَلِمَاتٍ فَيَقُولُ اكْتُبْ عَمَلَهُ وَأَجَلَهُ وَرِزْقَهُ وَشَقِيٌّ أَمْ سَعِيدٌ فَوَالَّذِي نَفْسِي بِيَدِهِ إِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ ‏ ‏الْكِتَابُ ‏ ‏فَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ فَيَدْخُلُهَا وَإِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ ‏ ‏الْكِتَابُ ‏ ‏فَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ فَيَدْخُلُهَا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ea64a5bd-1647-5cd4-9110-51fb2f011043', '889435ea-32e0-4b03-ab10-97e68c0eef82', '74', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سِنَانٍ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ خَالِدٍ الْحِمْصِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ الدَّيْلَمِيِّ ‏ ‏قَالَ ‏ ‏وَقَعَ فِي نَفْسِي شَيْءٌ مِنْ هَذَا الْقَدَرِ خَشِيتُ أَنْ يُفْسِدَ عَلَيَّ دِينِي وَأَمْرِي فَأَتَيْتُ ‏ ‏أُبَيَّ بْنَ كَعْبٍ ‏ ‏فَقُلْتُ ‏ ‏أَبَا الْمُنْذِرِ ‏ ‏إِنَّهُ قَدْ وَقَعَ فِي نَفْسِي شَيْءٌ مِنْ هَذَا الْقَدَرِ فَخَشِيتُ عَلَى دِينِي وَأَمْرِي فَحَدِّثْنِي مِنْ ذَلِكَ بِشَيْءٍ لَعَلَّ اللَّهَ أَنْ يَنْفَعَنِي بِهِ فَقَالَ ‏ ‏لَوْ أَنَّ اللَّهَ عَذَّبَ أَهْلَ سَمَاوَاتِهِ وَأَهْلَ أَرْضِهِ لَعَذَّبَهُمْ وَهُوَ غَيْرُ ظَالِمٍ لَهُمْ وَلَوْ رَحِمَهُمْ لَكَانَتْ رَحْمَتُهُ خَيْرًا لَهُمْ مِنْ أَعْمَالِهِمْ وَلَوْ كَانَ لَكَ مِثْلُ جَبَلِ ‏ ‏أُحُدٍ ‏ ‏ذَهَبًا ‏ ‏أَوْ مِثْلُ جَبَلِ ‏ ‏أُحُدٍ ‏ ‏تُنْفِقُهُ فِي سَبِيلِ اللَّهِ مَا قُبِلَ مِنْكَ حَتَّى تُؤْمِنَ بِالْقَدَرِ فَتَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ وَأَنَّ مَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ وَأَنَّكَ إِنْ مُتَّ عَلَى غَيْرِ هَذَا دَخَلْتَ النَّارَ وَلَا عَلَيْكَ أَنْ تَأْتِيَ أَخِي ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏فَتَسْأَلَهُ ‏ ‏فَأَتَيْتُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏فَسَأَلْتُهُ ‏ ‏فَذَكَرَ مِثْلَ مَا قَالَ ‏ ‏أُبَيٌّ ‏ ‏وَقَالَ لِي وَلَا عَلَيْكَ أَنْ تَأْتِيَ ‏ ‏حُذَيْفَةَ ‏ ‏فَأَتَيْتُ ‏ ‏حُذَيْفَةَ ‏ ‏فَسَأَلْتُهُ ‏ ‏فَقَالَ مِثْلَ مَا قَالَا وَقَالَ ائْتِ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏فَاسْأَلْهُ ‏ ‏فَأَتَيْتُ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏فَسَأَلْتُهُ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْ أَنَّ اللَّهَ عَذَّبَ أَهْلَ سَمَاوَاتِهِ وَأَهْلَ أَرْضِهِ لَعَذَّبَهُمْ وَهُوَ غَيْرُ ظَالِمٍ لَهُمْ وَلَوْ رَحِمَهُمْ لَكَانَتْ رَحْمَتُهُ خَيْرًا لَهُمْ مِنْ أَعْمَالِهِمْ وَلَوْ كَانَ لَكَ مِثْلُ ‏ ‏أُحُدٍ ‏ ‏ذَهَبًا ‏ ‏أَوْ مِثْلُ جَبَلِ ‏ ‏أُحُدٍ ‏ ‏ذَهَبًا ‏ ‏تُنْفِقُهُ فِي سَبِيلِ اللَّهِ مَا قَبِلَهُ مِنْكَ حَتَّى تُؤْمِنَ بِالْقَدَرِ كُلِّهِ فَتَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ وَمَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ وَأَنَّكَ إِنْ مُتَّ عَلَى غَيْرِ هَذَا دَخَلْتَ النَّارَ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5616fc91-6fde-5d42-bf8e-8304f883244c', '889435ea-32e0-4b03-ab10-97e68c0eef82', '75', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِيَدِهِ عُودٌ فَنَكَتَ فِي الْأَرْضِ ثُمَّ رَفَعَ رَأْسَهُ فَقَالَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ إِلَّا وَقَدْ كُتِبَ مَقْعَدُهُ مِنْ الْجَنَّةِ وَمَقْعَدُهُ مِنْ النَّارِ قِيلَ يَا رَسُولَ اللَّهِ أَفَلَا نَتَّكِلُ قَالَ لَا اعْمَلُوا وَلَا تَتَّكِلُوا فَكُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ ثُمَّ قَرَأَ ‏ { ‏فَأَمَّا مَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى فَسَنُيَسِّرُهُ لِلْيُسْرَى وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى وَكَذَّبَ بِالْحُسْنَى فَسَنُيَسِّرُهُ لِلْعُسْرَى ‏}', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9b957328-2896-52a5-9ea3-dab11738cc42', '889435ea-32e0-4b03-ab10-97e68c0eef82', '76', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَلِيُّ بْنُ مُحَمَّدٍ الطَّنَافِسِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَحَبُّ إِلَى اللَّهِ مِنْ الْمُؤْمِنِ الضَّعِيفِ وَفِي كُلٍّ خَيْرٌ احْرِصْ عَلَى مَا يَنْفَعُكَ وَاسْتَعِنْ بِاللَّهِ وَلَا تَعْجَزْ فَإِنْ أَصَابَكَ شَيْءٌ فَلَا تَقُلْ لَوْ أَنِّي فَعَلْتُ كَذَا وَكَذَا وَلَكِنْ قُلْ قَدَّرَ اللَّهُ وَمَا شَاءَ فَعَلَ فَإِنَّ لَوْ تَفْتَحُ عَمَلَ الشَّيْطَانِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('554290cf-d610-584c-8d6b-f6b48b4cf1c5', '889435ea-32e0-4b03-ab10-97e68c0eef82', '77', '‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَمَّارٍ ‏ ‏وَيَعْقُوبُ بْنُ حُمَيْدِ بْنِ كَاسِبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏سَمِعَ ‏ ‏طَاوُسًا ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُخْبِرُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏احْتَجَّ ‏ ‏آدَمُ ‏ ‏وَمُوسَى ‏ ‏عَلَيْهِمَا السَّلَام ‏ ‏فَقَالَ لَهُ ‏ ‏مُوسَى ‏ ‏يَا ‏ ‏آدَمُ ‏ ‏أَنْتَ أَبُونَا ‏ ‏خَيَّبْتَنَا ‏ ‏وَأَخْرَجْتَنَا مِنْ الْجَنَّةِ بِذَنْبِكَ فَقَالَ لَهُ ‏ ‏آدَمُ ‏ ‏يَا ‏ ‏مُوسَى ‏ ‏اصْطَفَاكَ ‏ ‏اللَّهُ بِكَلَامِهِ وَخَطَّ لَكَ التَّوْرَاةَ بِيَدِهِ أَتَلُومُنِي عَلَى أَمْرٍ قَدَّرَهُ اللَّهُ عَلَيَّ قَبْلَ أَنْ يَخْلُقَنِي بِأَرْبَعِينَ سَنَةً ‏ ‏فَحَجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏فَحَجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏فَحَجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏ثَلَاثًا ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('af914d27-b6b2-5e1d-bb4c-d8681e604db9', '889435ea-32e0-4b03-ab10-97e68c0eef82', '78', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَامِرِ بْنِ زُرَارَةَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنْ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُؤْمِنُ عَبْدٌ حَتَّى يُؤْمِنَ بِأَرْبَعٍ بِاللَّهِ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنِّي رَسُولُ اللَّهِ وَبِالْبَعْثِ بَعْدَ الْمَوْتِ وَالْقَدَرِ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b6e73643-48a0-5ef1-8bff-73de87efe9b0', '889435ea-32e0-4b03-ab10-97e68c0eef82', '79', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَلِيُّ بْنُ مُحَمَّدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏طَلْحَةُ بْنُ يَحْيَى بْنِ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏عَائِشَةَ بِنْتِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏دُعِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى جِنَازَةِ غُلَامٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ طُوبَى لِهَذَا عُصْفُورٌ مِنْ عَصَافِيرِ الْجَنَّةِ لَمْ يَعْمَلْ السُّوءَ وَلَمْ يُدْرِكْهُ قَالَ ‏ ‏أَوَ غَيْرُ ذَلِكَ يَا ‏ ‏عَائِشَةُ ‏ ‏إِنَّ اللَّهَ خَلَقَ لِلْجَنَّةِ أَهْلًا خَلَقَهُمْ لَهَا وَهُمْ فِي ‏ ‏أَصْلَابِ ‏ ‏آبَائِهِمْ وَخَلَقَ لِلنَّارِ أَهْلًا خَلَقَهُمْ لَهَا وَهُمْ فِي ‏ ‏أَصْلَابِ ‏ ‏آبَائِهِمْ ‏', 'سنن ابن ماجه — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
